-- Link video: chỉ điền khi ô còn trống — link giáo viên đã tự gắn ở /gv/noi-dung được giữ nguyên.
on conflict (content_id) do update set title = excluded.title, ku_id = excluded.ku_id,
  duration_sec = case when contents.url is null or contents.url = '' then excluded.duration_sec else contents.duration_sec end,
  nguon = case when contents.url is null or contents.url = '' then excluded.nguon else contents.nguon end,
  url = case when contents.url is null or contents.url = '' then excluded.url else contents.url end;

insert into error_dictionary (error_code, ku_id, misconception, remediation_id) values
  ('E-PT2-01', 'C1-B1-M1', 'Nhận dạng phương trình bậc nhất hai ẩn sai: coi xy, x², 1/x là bậc nhất, hoặc cho rằng a và b phải cùng khác 0. Ví dụ: xy + 2 = 0 là phương trình bậc nhất hai ẩn; 0x + 4y = 8 không phải', 'VBH-PT2-01'),
  ('E-PT2-02', 'C1-B1-M1', 'Kiểm tra nghiệm hoặc tìm tham số mà thay nhầm thứ tự x, y trong cặp số, hoặc tính sai dấu khi thay. Ví dụ: (1; 2) với x + 2y = 5: thay 2 + 2·1 = 4', 'VBH-PT2-02'),
  ('E-PT2-03', 'C1-B1-M2', 'Cho rằng phương trình bậc nhất hai ẩn chỉ có một nghiệm, viết nghiệm tổng quát sai, hoặc nhầm đường thẳng y = c với x = c. Ví dụ: 0x + 2y = 4 biểu diễn bởi đường thẳng x = 2', 'VBH-PT2-03'),
  ('E-HPT-01', 'C1-B1-M3', 'Kết luận một cặp số là nghiệm của hệ khi nó mới thoả một trong hai phương trình. Ví dụ: (3; 0) là nghiệm của hệ x + y = 3, x − y = 1', 'VBH-HPT-01'),
  ('E-HPT-02', 'C1-B2-M1', 'Khi rút và thế, chuyển vế sai dấu hoặc thế biểu thức mà không đặt trong ngoặc nên quên đổi dấu. Ví dụ: Thế y = 3 − x vào 2x − y = 0 được 2x − 3 − x = 0', 'VBH-HPT-02'),
  ('E-HPT-03', 'C1-B2-M2', 'Cộng đại số mà nhân hệ số không đủ các hạng tử, trừ từng vế quên đổi dấu, hoặc chọn hệ số không khử được ẩn. Ví dụ: Nhân 2x − y = 3 với 3 được 6x − y = 9', 'VBH-HPT-03'),
  ('E-HPT-04', 'C1-B2-M1', 'Kết luận sai số nghiệm khi gặp 0x = c, hoặc tìm được một ẩn rồi kết luận thiếu, sai ẩn còn lại. Ví dụ: Gặp 0y = 2 kết luận y = 0; hệ trùng nhau kết luận vô nghiệm', 'VBH-HPT-04'),
  ('E-BTH-01', 'C1-B3-M1', 'Chọn ẩn không rõ đơn vị, đặt điều kiện sai (cho số học sinh là số thực, số âm) hoặc không đối chiếu điều kiện. Ví dụ: Gọi số học sinh nam là x, điều kiện x ∈ ℝ', 'VBH-BTH-01'),
  ('E-BTH-02', 'C1-B3-M1', 'Lập phương trình sai quan hệ trong đề: nhầm "hơn" với "gấp", đảo vai hai đại lượng, dùng nửa chu vi thay chu vi. Ví dụ: Chu vi 34 m viết x + y = 34', 'VBH-BTH-02'),
  ('E-BTH-03', 'C1-B3-M1B', 'Dùng sai s = v·t, nhầm vận tốc xuôi – ngược dòng, hoặc quên nhân thời gian khi hai xe đi ngược chiều gặp nhau. Ví dụ: Hai xe gặp nhau sau 2 giờ: x + y = 180', 'VBH-BTH-03'),
  ('E-BTH-04', 'C1-B3-M1C', 'Bài toán làm chung – làm riêng mà cộng thời gian của từng đội (x + y = t) thay vì cộng năng suất (1/x + 1/y = 1/t). Ví dụ: Vòi A 4 giờ, vòi B 6 giờ thì cùng chảy hết 10 giờ', 'VBH-BTH-04')
on conflict (error_code) do update set ku_id = excluded.ku_id, misconception = excluded.misconception,
  remediation_id = excluded.remediation_id;

