  ('C1-B3-M1-Q13', 'C1-B3-M1', 2, 'Mua $2$ kg táo và $3$ kg cam hết $170 000$ đồng; mua $3$ kg táo và $2$ kg cam hết $180 000$ đồng. Gọi giá $1$ kg táo là $x$, giá $1$ kg cam là $y$ (đồng). Hệ phương trình là:', 'A', 60, null, 'nhap', null, null, null),
