  ('C1-B3-M1-Q15', 'C1-B3-M1', 3, 'Một số có hai chữ số, chữ số hàng chục gấp đôi chữ số hàng đơn vị và tổng hai chữ số bằng $9$. Số đó là:', 'A', 90, null, 'nhap', null, null, null),
  ('C1-B3-M1-Q16', 'C1-B3-M1', 4, 'Một mảnh vườn hình chữ nhật có chu vi $46$ m. Nếu tăng chiều rộng thêm $3$ m và giảm chiều dài $2$ m thì mảnh vườn trở thành hình vuông. Diện tích mảnh vườn ban đầu là:', 'A', 120, null, 'nhap', null, null, null),
  ('C1-B3-M1B-Q01', 'C1-B3-M1B', 1, 'Một ô tô đi với vận tốc $v$ (km/h) trong $t$ (giờ) thì được quãng đường $s$ (km) là:', 'A', 45, null, 'nhap', null, null, null),
  ('C1-B3-M1B-Q02', 'C1-B3-M1B', 1, 'Ca nô có vận tốc riêng $x$ km/h, vận tốc dòng nước $y$ km/h. Vận tốc của ca nô khi xuôi dòng là:', 'A', 45, null, 'nhap', null, null, null),
  ('C1-B3-M1B-Q03', 'C1-B3-M1B', 2, 'Hai xe khởi hành cùng lúc từ hai địa điểm cách nhau $180$ km, đi ngược chiều và gặp nhau sau $2$ giờ. Gọi vận tốc hai xe là $x$, $y$ (km/h). Phương trình đúng là:', 'A', 60, null, 'nhap', null, null, null),
  ('C1-B3-M1B-Q04', 'C1-B3-M1B', 2, 'Một ca nô xuôi dòng với vận tốc $30$ km/h, ngược dòng với vận tốc $24$ km/h. Vận tốc dòng nước là:', 'A', 60, null, 'nhap', null, null, null),
  ('C1-B3-M1B-Q05', 'C1-B3-M1B', 3, 'Hai xe đi ngược chiều từ $A$ và $B$ cách nhau $180$ km, gặp nhau sau $2$ giờ; xe đi từ $A$ nhanh hơn xe đi từ $B$ là $10$ km/h. Vận tốc xe đi từ $A$ là:', 'A', 90, null, 'nhap', null, null, null),
  ('C1-B3-M1B-Q06', 'C1-B3-M1B', 3, 'Một người đi xe đạp từ $A$ đến $B$ với vận tốc $15$ km/h rồi quay về với vận tốc $12$ km/h, cả đi và về hết $3$ giờ. Gọi quãng đường $AB$ là $x$ (km). Phương trình đúng là:', 'A', 90, null, 'nhap', null, null, null),
  ('C1-B3-M1B-Q07', 'C1-B3-M1B', 4, 'Một người đi xe đạp từ $A$ đến $B$ với vận tốc $15$ km/h rồi quay về với vận tốc $12$ km/h, cả đi và về hết $3$ giờ. Quãng đường $AB$ dài:', 'A', 120, null, 'nhap', null, null, null),
  ('C1-B3-M1B-Q08', 'C1-B3-M1B', 4, 'Một ca nô xuôi dòng $60$ km rồi ngược dòng $40$ km, hết tất cả $5$ giờ; vận tốc dòng nước là $4$ km/h. Gọi vận tốc riêng của ca nô là $x$ (km/h, $x > 4$). Phương trình đúng là:', 'A', 120, null, 'nhap', null, null, null),
  ('C1-B3-M1B-Q09', 'C1-B3-M1B', 1, 'Ca nô có vận tốc riêng $x$ km/h, vận tốc dòng nước $y$ km/h. Vận tốc của ca nô khi ngược dòng là:', 'A', 45, null, 'nhap', null, null, null),
  ('C1-B3-M1B-Q10', 'C1-B3-M1B', 1, 'Một xe đi quãng đường $120$ km với vận tốc $40$ km/h. Thời gian xe đi là:', 'A', 45, null, 'nhap', null, null, null),
  ('C1-B3-M1B-Q11', 'C1-B3-M1B', 2, 'Hai xe khởi hành cùng lúc từ hai địa điểm cách nhau $150$ km, đi ngược chiều và gặp nhau sau $1{,}5$ giờ. Tổng vận tốc của hai xe là:', 'A', 60, null, 'nhap', null, null, null),
  ('C1-B3-M1B-Q12', 'C1-B3-M1B', 2, 'Một ca nô xuôi dòng với vận tốc $28$ km/h, ngược dòng với vận tốc $22$ km/h. Vận tốc riêng của ca nô là:', 'A', 60, null, 'nhap', null, null, null),
  ('C1-B3-M1B-Q13', 'C1-B3-M1B', 2, 'Xe thứ nhất đi trong $3$ giờ và xe thứ hai đi trong $2$ giờ thì tổng quãng đường hai xe đi được là $260$ km. Gọi vận tốc xe thứ nhất, xe thứ hai lần lượt là $x$, $y$ (km/h). Phương trình đúng là:', 'A', 60, null, 'nhap', null, null, null),
  ('C1-B3-M1B-Q14', 'C1-B3-M1B', 3, 'Hai xe khởi hành cùng lúc từ hai địa điểm cách nhau $150$ km, đi ngược chiều và gặp nhau sau $1{,}5$ giờ; xe thứ nhất nhanh hơn xe thứ hai $10$ km/h. Vận tốc xe thứ hai là:', 'A', 90, null, 'nhap', null, null, null),
  ('C1-B3-M1B-Q15', 'C1-B3-M1B', 3, 'Một ca nô xuôi dòng trong $3$ giờ được $81$ km, ngược dòng trong $2$ giờ được $42$ km. Vận tốc dòng nước là:', 'A', 90, null, 'nhap', null, null, null),
  ('C1-B3-M1B-Q16', 'C1-B3-M1B', 4, 'Một người đi từ $A$ đến $B$. Nếu đi với vận tốc $40$ km/h thì đến muộn $1$ giờ so với dự định; nếu đi với vận tốc $60$ km/h thì đến sớm $1$ giờ. Quãng đường $AB$ dài:', 'A', 120, null, 'nhap', null, null, null),
  ('C1-B3-M1C-Q01', 'C1-B3-M1C', 1, 'Một đội làm xong một công việc trong $x$ ngày. Trong $1$ ngày, đội đó làm được:', 'A', 45, null, 'nhap', null, null, null),
  ('C1-B3-M1C-Q02', 'C1-B3-M1C', 1, 'Vòi $A$ chảy đầy bể trong $4$ giờ, vòi $B$ chảy đầy bể trong $6$ giờ. Trong $1$ giờ, cả hai vòi cùng chảy được:', 'A', 45, null, 'nhap', null, null, null),
  ('C1-B3-M1C-Q03', 'C1-B3-M1C', 2, 'Vòi $A$ chảy đầy bể trong $4$ giờ, vòi $B$ chảy đầy bể trong $6$ giờ. Hai vòi cùng chảy thì đầy bể sau:', 'A', 60, null, 'nhap', null, null, null),
  ('C1-B3-M1C-Q04', 'C1-B3-M1C', 2, 'Hai đội cùng làm thì xong công việc trong $12$ ngày. Gọi thời gian đội I, đội II làm một mình xong việc lần lượt là $x$, $y$ (ngày). Phương trình đúng là:', 'A', 60, null, 'nhap', null, null, null),
  ('C1-B3-M1C-Q05', 'C1-B3-M1C', 3, 'Theo kế hoạch, hai tổ sản xuất $600$ sản phẩm. Thực tế tổ I vượt mức $10\%$, tổ II vượt mức $20\%$ nên làm được $685$ sản phẩm. Gọi số sản phẩm theo kế hoạch của tổ I, tổ II là $x$, $y$. Hệ phương trình đúng là:', 'A', 90, null, 'nhap', null, null, null),
  ('C1-B3-M1C-Q06', 'C1-B3-M1C', 3, 'Theo kế hoạch, hai tổ sản xuất $600$ sản phẩm. Thực tế tổ I vượt mức $10\%$, tổ II vượt mức $20\%$ nên làm được $685$ sản phẩm. Số sản phẩm theo kế hoạch của tổ I là:', 'A', 90, null, 'nhap', null, null, null),
  ('C1-B3-M1C-Q07', 'C1-B3-M1C', 4, 'Hai đội cùng làm thì xong việc trong $12$ ngày. Làm chung $8$ ngày thì đội I nghỉ, đội II làm tiếp $7$ ngày nữa thì xong. Đội II làm một mình thì xong việc sau:', 'A', 120, null, 'nhap', null, null, null),
  ('C1-B3-M1C-Q08', 'C1-B3-M1C', 4, 'Hai vòi cùng chảy thì đầy bể sau $2$ giờ $24$ phút. Chảy riêng thì vòi I đầy bể nhanh hơn vòi II $2$ giờ. Gọi thời gian vòi I chảy riêng đầy bể là $x$ giờ $(x > 0)$. Phương trình đúng là:', 'A', 120, null, 'nhap', null, null, null),
  ('C1-B3-M1C-Q09', 'C1-B3-M1C', 1, 'Một vòi nước chảy riêng thì đầy bể trong $5$ giờ. Trong $2$ giờ, vòi chảy được:', 'A', 45, null, 'nhap', null, null, null),
  ('C1-B3-M1C-Q10', 'C1-B3-M1C', 1, 'Hai đội cùng làm thì mỗi ngày làm được $\dfrac{1}{8}$ công việc. Hai đội cùng làm thì xong công việc trong:', 'A', 45, null, 'nhap', null, null, null),
  ('C1-B3-M1C-Q11', 'C1-B3-M1C', 2, 'Đội I làm một mình xong việc trong $10$ ngày, đội II trong $15$ ngày. Một ngày cả hai đội cùng làm được:', 'A', 60, null, 'nhap', null, null, null),
  ('C1-B3-M1C-Q12', 'C1-B3-M1C', 2, 'Đội I làm một mình xong việc trong $10$ ngày, đội II trong $15$ ngày. Hai đội cùng làm thì xong việc trong:', 'A', 60, null, 'nhap', null, null, null),
  ('C1-B3-M1C-Q13', 'C1-B3-M1C', 2, 'Theo kế hoạch tổ I làm $x$ sản phẩm. Thực tế tổ I vượt mức $15\%$. Số sản phẩm thực tế tổ I làm được là:', 'A', 60, null, 'nhap', null, null, null),
  ('C1-B3-M1C-Q14', 'C1-B3-M1C', 3, 'Hai vòi nước cùng chảy thì đầy bể sau $6$ giờ. Nếu vòi I chảy $2$ giờ và vòi II chảy $3$ giờ thì được $\dfrac{2}{5}$ bể. Gọi thời gian vòi I, vòi II chảy riêng đầy bể lần lượt là $x$, $y$ (giờ). Hệ phương trình đúng là:', 'A', 90, null, 'nhap', null, null, null),
  ('C1-B3-M1C-Q15', 'C1-B3-M1C', 3, 'Hai vòi nước cùng chảy thì đầy bể sau $6$ giờ. Nếu vòi I chảy $2$ giờ và vòi II chảy $3$ giờ thì được $\dfrac{2}{5}$ bể. Thời gian vòi I chảy riêng đầy bể là:', 'A', 90, null, 'nhap', null, null, null),
  ('C1-B3-M1C-Q16', 'C1-B3-M1C', 4, 'Theo kế hoạch, hai tổ sản xuất $900$ sản phẩm. Thực tế tổ I vượt mức $20\%$, tổ II vượt mức $15\%$ nên làm được $1 055$ sản phẩm. Số sản phẩm theo kế hoạch của tổ II là:', 'A', 120, null, 'nhap', null, null, null)
