insert into error_hints (error_code, tier, hint_text) values
  ('E-PT2-01', 1, 'Mỗi hạng tử chứa ẩn có đúng một ẩn với số mũ $1$ không? Có ẩn nằm ở mẫu không?'),
  ('E-PT2-01', 2, 'Phương trình bậc nhất hai ẩn có dạng $ax + by = c$, trong đó $a \ne 0$ hoặc $b \ne 0$ (chỉ cần một hệ số khác $0$). Các hạng tử $xy$, $x^{2}$, $\dfrac{1}{x}$ đều không phải bậc nhất.'),
  ('E-PT2-01', 3, 'Ví dụ: $0x + 4y = 8$ là phương trình bậc nhất hai ẩn $(b = 4 \ne 0)$; $xy + 2 = 0$ thì không.'),
  ('E-PT2-02', 1, 'Trong cặp số $(x_{0}; y_{0})$, số nào thay cho $x$, số nào thay cho $y$?'),
  ('E-PT2-02', 2, 'Số đứng trước trong cặp là giá trị của $x$, số đứng sau là giá trị của $y$. Thay đúng vị trí, đặt số âm trong ngoặc rồi tính hai vế.'),
  ('E-PT2-02', 3, 'Ví dụ: $(1; 2)$ với $x + 2y = 5$: $1 + 2\cdot 2 = 5$, đúng, nên $(1; 2)$ là nghiệm.'),
  ('E-PT2-03', 1, 'Chọn $x = 0$, $x = 1$, $x = 2$ thì mỗi lần có tìm được $y$ không? Vậy có bao nhiêu nghiệm?'),
  ('E-PT2-03', 2, 'Phương trình bậc nhất hai ẩn có vô số nghiệm; tập nghiệm là một đường thẳng. Khi $a = 0$: $y = \dfrac{c}{b}$, đường thẳng song song $Ox$; khi $b = 0$: $x = \dfrac{c}{a}$, song song $Oy$.'),
  ('E-PT2-03', 3, 'Ví dụ: $0x + 2y = 4 \Leftrightarrow y = 2$, đường thẳng song song với trục $Ox$, cắt $Oy$ tại $(0; 2)$.'),
  ('E-HPT-01', 1, 'Cặp số này đã thoả phương trình thứ hai chưa, hay mới thoả phương trình thứ nhất?'),
  ('E-HPT-01', 2, 'Nghiệm của hệ phải là nghiệm chung của cả hai phương trình. Thay cặp số vào lần lượt từng phương trình; chỉ cần một phương trình sai là không phải nghiệm của hệ.'),
  ('E-HPT-01', 3, 'Ví dụ: $(3; 0)$ thoả $x + y = 3$ nhưng $3 - 0 = 3 \ne 1$ nên không phải nghiệm của hệ $x + y = 3$, $x - y = 1$.'),
  ('E-HPT-02', 1, 'Khi thế một biểu thức vào chỗ của $y$, em đã đặt biểu thức đó trong ngoặc chưa?'),
  ('E-HPT-02', 2, 'Rút một ẩn rồi thay cả biểu thức (đặt trong ngoặc) vào phương trình còn lại; khi bỏ ngoặc có dấu "$-$" đứng trước thì đổi dấu mọi hạng tử. Chuyển vế phải đổi dấu.'),
  ('E-HPT-02', 3, 'Ví dụ: thế $y = 3 - x$ vào $2x - y = 0$: $2x - (3 - x) = 0 \Leftrightarrow 3x = 3 \Leftrightarrow x = 1$.'),
  ('E-HPT-03', 1, 'Khi nhân một phương trình với một số, em đã nhân với mọi hạng tử ở cả hai vế chưa?'),
  ('E-HPT-03', 2, 'Nhân hai vế với cùng một số: nhân mọi hạng tử. Chọn số nhân sao cho hệ số của một ẩn bằng nhau (rồi trừ) hoặc đối nhau (rồi cộng). Trừ từng vế thì đổi dấu mọi hạng tử của phương trình bị trừ.'),
  ('E-HPT-03', 3, 'Ví dụ: $2x - y = 3$ nhân $3$ được $6x - 3y = 9$, không phải $6x - y = 9$.'),
  ('E-HPT-04', 1, 'Phương trình $0y = 2$ có số $y$ nào thoả mãn không? Còn $0y = 0$ thì sao?'),
  ('E-HPT-04', 2, 'Gặp $0x = c$: nếu $c \ne 0$ thì hệ vô nghiệm; nếu $c = 0$ thì hệ có vô số nghiệm. Tìm được một ẩn thì phải thay lại để tìm ẩn kia rồi mới kết luận cặp nghiệm.'),
  ('E-HPT-04', 3, 'Ví dụ: hệ $x + y = 3$, $x + y = 5$ dẫn đến $0y = 2$, không có $y$ nào thoả nên hệ vô nghiệm.'),
  ('E-BTH-01', 1, 'Ẩn em chọn chỉ đại lượng gì, đơn vị gì? Nó có thể là số âm hay số lẻ không?'),
  ('E-BTH-01', 2, 'Chọn ẩn: ghi rõ đại lượng và đơn vị. Đặt điều kiện theo thực tế (số người là số tự nhiên khác $0$, độ dài dương…). Giải xong phải đối chiếu điều kiện rồi mới trả lời.'),
  ('E-BTH-01', 3, 'Ví dụ: gọi số học sinh nam là $x$ (em), điều kiện $x \in \mathbb{N}$*, $x < 40$.'),
  ('E-BTH-02', 1, 'Câu nào trong đề cho em phương trình thứ nhất, câu nào cho phương trình thứ hai?'),
  ('E-BTH-02', 2, 'Dịch từng câu: "tổng" $\to$ cộng; "hơn … là $a$" $\to$ hiệu bằng $a$; "gấp $k$ lần" $\to$ nhân $k$; chu vi hình chữ nhật $= 2$(dài $+$ rộng). Kiểm tra lại bằng cách thay nghiệm vào lời văn.'),
  ('E-BTH-02', 3, 'Ví dụ: chu vi $34$ m, dài hơn rộng $7$ m: $2(x + y) = 34$ tức $x + y = 17$, và $x - y = 7$.'),
  ('E-BTH-03', 1, 'Quãng đường bằng vận tốc nhân với gì? Dòng nước giúp hay cản ca nô khi xuôi dòng?'),
  ('E-BTH-03', 2, '$s = v\cdot t$, $t = \dfrac{s}{v}$. Xuôi dòng: $v +$ vnước; ngược dòng: $v -$ vnước. Hai xe đi ngược chiều gặp nhau: tổng quãng đường hai xe đi được bằng khoảng cách ban đầu.'),
  ('E-BTH-03', 3, 'Ví dụ: hai xe gặp nhau sau $2$ giờ trên quãng $180$ km: $2x + 2y = 180$.'),
  ('E-BTH-04', 1, 'Trong $1$ giờ, mỗi vòi chảy được bao nhiêu phần bể? Cùng chảy thì cộng thời gian hay cộng phần bể?'),
  ('E-BTH-04', 2, 'Làm xong việc trong $x$ đơn vị thời gian thì năng suất là $\dfrac{1}{x}$ công việc mỗi đơn vị. Làm chung: cộng năng suất, $\dfrac{1}{x} + \dfrac{1}{y} = \dfrac{1}{t}$. Đổi giờ – phút về cùng đơn vị trước khi lập phương trình.'),
  ('E-BTH-04', 3, 'Ví dụ: vòi $A 4$ giờ, vòi $B 6$ giờ: $\dfrac{1}{4} + \dfrac{1}{6} = \dfrac{5}{12}$ bể mỗi giờ, nên cùng chảy đầy bể sau $\dfrac{12}{5} = 2{,}4$ giờ.')
on conflict (error_code, tier) do update set hint_text = excluded.hint_text;

insert into micro_lessons (content_id, dan, quy_tac, vi_du, tu_lam) values
  ('VBH-PT2-01', 'Phương trình bậc nhất hai ẩn có một "khuôn" rất rõ. Nhìn đúng khuôn là nhận ra ngay.', 'Dạng $ax + by = c$ với $a$, $b$, $c$ là số đã biết và $a \ne 0$ hoặc $b \ne 0$. Mỗi hạng tử chứa ẩn chỉ có một ẩn, số mũ $1$, không nằm ở mẫu.', '[{"de":"$xy + 2 = 0$ có phải phương trình bậc nhất hai ẩn?","giai":"Cách nghĩ sai: có hai ẩn $x$, $y$ nên đúng. Cách đúng: hạng tử $xy$ chứa hai ẩn nhân nhau (bậc $2$), nên không phải."},{"de":"$0x + 4y = 8$ có phải phương trình bậc nhất hai ẩn?","giai":"Có: $a = 0$ nhưng $b = 4 \\ne 0$."}]'::jsonb, '[{"de":"$3x - y = 2$ có phải phương trình bậc nhất hai ẩn?","dapAn":"Có","giaiThich":"$a = 3$, $b = -1$.","dapAnGoc":"Có"},{"de":"$x^{2} + y = 4$ có phải không?","dapAn":"Không","giaiThich":"Có $x^{2}$.","dapAnGoc":"Không"}]'::jsonb),
  ('VBH-PT2-02', 'Kiểm tra nghiệm chỉ là "thay số rồi tính" — nhưng thay nhầm chỗ là sai cả bài.', 'Cặp $(x_{0}; y_{0})$: số đứng trước thay cho $x$, số đứng sau thay cho $y$. Đặt số âm trong ngoặc. Hai vế bằng nhau thì là nghiệm.', '[{"de":"$(1; 2)$ có là nghiệm của $x + 2y = 5$?","giai":"Cách nghĩ sai: thay $2 + 2\\cdot 1 = 4 \\ne 5$ nên không. Cách đúng: $x = 1$, $y = 2$: $1 + 2\\cdot 2 = 5$, là nghiệm."},{"de":"Tìm $m$ để $(1; 2)$ là nghiệm của $mx + y = 5$.","giai":"$m\\cdot 1 + 2 = 5 \\Leftrightarrow m = 3$."}]'::jsonb, '[{"de":"$(2; -1)$ có là nghiệm của $3x + 2y = 4$?","dapAn":"Có","giaiThich":"$6 + 2\\cdot (-1) = 4$.","dapAnGoc":"Có"},{"de":"$(0; 5)$ có là nghiệm của $x + 2y = 5$?","dapAn":"Không","giaiThich":"$0 + 10 = 10$.","dapAnGoc":"Không"}]'::jsonb),
  ('VBH-PT2-03', 'Một phương trình bậc nhất hai ẩn không có "một đáp số" — nó có cả một đường thẳng nghiệm.', 'Cho $x$ một giá trị bất kì luôn tìm được $y$, nên có vô số nghiệm; nghiệm tổng quát ($x; y$ theo $x$). Tập nghiệm là đường thẳng $ax + by = c$: $a = 0 \to y = \dfrac{c}{b}$ song song $Ox$; $b = 0 \to x = \dfrac{c}{a}$ song song $Oy$.', '[{"de":"Biểu diễn tập nghiệm của $0x + 2y = 4$.","giai":"Cách nghĩ sai: đường thẳng $x = 2$. Cách đúng: $2y = 4 \\Leftrightarrow y = 2$, đường thẳng song song với $Ox$, cắt $Oy$ tại $(0; 2)$."},{"de":"Viết nghiệm tổng quát của $x + y = 3$.","giai":"$y = 3 - x$, nghiệm tổng quát $(x; 3 - x)$, $x \\in \\mathbb{R}$."}]'::jsonb, '[{"de":"$3x + 0y = 6$ biểu diễn bởi đường thẳng nào?","dapAn":"$x = 2$","giaiThich":"$b = 0$, song song $Oy$.","dapAnGoc":"x = 2"},{"de":"$x - y = 1$ có bao nhiêu nghiệm?","dapAn":"Vô số","giaiThich":"Mỗi $x$ cho một $y$.","dapAnGoc":"Vô số"}]'::jsonb),
  ('VBH-HPT-01', 'Nghiệm của hệ phải "qua được hai cửa": cả hai phương trình.', 'Cặp $(x_{0}; y_{0})$ là nghiệm của hệ khi nó là nghiệm của cả hai phương trình. Thay vào phương trình thứ nhất, rồi thay vào phương trình thứ hai.', '[{"de":"$(3; 0)$ có là nghiệm của hệ $x + y = 3$, $x - y = 1$?","giai":"Cách nghĩ sai: $3 + 0 = 3$ đúng nên là nghiệm. Cách đúng: còn phương trình thứ hai $3 - 0 = 3 \\ne 1$, nên không phải nghiệm của hệ."},{"de":"$(2; 1)$ có là nghiệm của hệ trên?","giai":"$2 + 1 = 3$ và $2 - 1 = 1$, đúng cả hai: là nghiệm."}]'::jsonb, '[{"de":"$(1; 2)$ có là nghiệm của hệ $x + y = 3$, $2x - y = 0$?","dapAn":"Có","giaiThich":"$3 = 3$ và $0 = 0$.","dapAnGoc":"Có"},{"de":"$(1; 0)$ có là nghiệm của hệ $x + y = 3$, $x - y = 1$?","dapAn":"Không","giaiThich":"$1 + 0 \\ne 3$.","dapAnGoc":"Không"}]'::jsonb),
  ('VBH-HPT-02', 'Phương pháp thế hay sai ở đúng một chỗ: quên ngoặc khi thế.', 'Rút một ẩn từ phương trình đơn giản (chuyển vế nhớ đổi dấu), thay cả biểu thức trong ngoặc vào phương trình còn lại, giải phương trình một ẩn, rồi thay ngược để tìm ẩn kia.', '[{"de":"Thế $y = 3 - x$ vào $2x - y = 0$.","giai":"Cách nghĩ sai: $2x - 3 - x = 0$. Cách đúng: $2x - (3 - x) = 0 \\Leftrightarrow 2x - 3 + x = 0 \\Leftrightarrow x = 1$, $y = 2$."},{"de":"Giải hệ $y = x + 1$, $2x + y = 7$.","giai":"$2x + (x + 1) = 7 \\Leftrightarrow x = 2$, $y = 3$."}]'::jsonb, '[{"de":"Từ $x - 3y = 2$ rút $x$.","dapAn":"$x = 2 + 3y$","giaiThich":"Chuyển $-3y$ sang vế phải thành $+3y$.","dapAnGoc":"x = 2 + 3y"},{"de":"Giải hệ $x = 2y$, $x + y = 6$.","dapAn":"$(4; 2)$","giaiThich":"$3y = 6$.","dapAnGoc":"(4; 2)"}]'::jsonb),
  ('VBH-HPT-03', 'Cộng đại số nhanh, nhưng nhân thiếu một hạng tử là lệch cả hệ.', 'Nhân hai vế của phương trình với cùng một số: nhân mọi hạng tử. Hệ số của một ẩn bằng nhau thì trừ từng vế, đối nhau thì cộng từng vế. Trừ thì đổi dấu mọi hạng tử bị trừ.', '[{"de":"Nhân $2x - y = 3$ với $3$.","giai":"Cách nghĩ sai: $6x - y = 9$. Cách đúng: $6x - 3y = 9$."},{"de":"Giải hệ $x + y = 7$, $x - y = 1$.","giai":"Cộng từng vế: $2x = 8 \\Leftrightarrow x = 4$, $y = 3$."}]'::jsonb, '[{"de":"Trừ từng vế $3x + 2y = 7$ cho $x + 2y = 5$.","dapAn":"$2x = 2$","giaiThich":"$y$ bị khử.","dapAnGoc":"2x = 2"},{"de":"Giải hệ $3x + 2y = 1$, $2x - 3y = 5$.","dapAn":"$(1; -1)$","giaiThich":"Nhân $3$ và $2$ rồi cộng: $13x = 13$.","dapAnGoc":"(1; −1)"}]'::jsonb),
  ('VBH-HPT-04', 'Có hệ không có nghiệm, có hệ nghiệm "nhiều vô kể". Đọc đúng dấu hiệu là kết luận đúng.', 'Khi biến đổi được $0x = c$: $c \ne 0$ thì hệ vô nghiệm, $c = 0$ thì hệ có vô số nghiệm. Hệ có nghiệm duy nhất thì phải ghi đủ cặp $(x; y)$.', '[{"de":"Hệ $x + y = 3$, $x + y = 5$ dẫn đến $0y = 2$.","giai":"Cách nghĩ sai: $y = 0$. Cách đúng: không có $y$ nào để $0\\cdot y = 2$, hệ vô nghiệm."},{"de":"Hệ $x - y = 1$, $2x - 2y = 2$.","giai":"Phương trình thứ hai gấp đôi phương trình thứ nhất: vô số nghiệm $(x; x - 1)$."}]'::jsonb, '[{"de":"$0x = 0$ thì hệ có bao nhiêu nghiệm?","dapAn":"Vô số","giaiThich":"Mọi $x$ đều thoả.","dapAnGoc":"Vô số"},{"de":"$0x = 5$ thì sao?","dapAn":"Vô nghiệm","giaiThich":"Không $x$ nào thoả.","dapAnGoc":"Vô nghiệm"}]'::jsonb),
  ('VBH-BTH-01', 'Bước chọn ẩn tưởng đơn giản nhưng quyết định cả lời giải có hợp lí hay không.', 'Chọn ẩn: ghi rõ đại lượng và đơn vị. Đặt điều kiện theo thực tế (số người: số tự nhiên khác $0$; độ dài, vận tốc: số dương; nhỏ hơn tổng nếu có). Cuối bài đối chiếu điều kiện.', '[{"de":"Gọi số học sinh nam là $x$ trong lớp $40$ em.","giai":"Cách nghĩ sai: $x \\in \\mathbb{R}$. Cách đúng: $x \\in \\mathbb{N}$*, $x < 40$."},{"de":"Giải ra chiều rộng âm thì sao?","giai":"Không thoả điều kiện, loại nghiệm đó."}]'::jsonb, '[{"de":"Ẩn là vận tốc (km/h), điều kiện?","dapAn":"$x > 0$","giaiThich":"Vận tốc dương.","dapAnGoc":"x > 0"},{"de":"Ẩn là số sản phẩm, điều kiện?","dapAn":"$x \\in \\mathbb{N}$","giaiThich":"Số sản phẩm là số tự nhiên.","dapAnGoc":"x ∈ ℕ"}]'::jsonb),
  ('VBH-BTH-02', 'Lời văn có "từ khoá". Dịch từng câu sang ngôn ngữ toán là lập được hệ.', '"Tổng" $\to$ cộng; "hơn $a$" $\to$ hiệu bằng $a$; "gấp $k$ lần" $\to$ nhân $k$; chu vi hình chữ nhật $= 2$(dài $+$ rộng); tăng $10\% \to$ nhân $1{,}1$. Lập xong thì thử nghiệm vào lời văn.', '[{"de":"Chu vi $34$ m, dài hơn rộng $7$ m.","giai":"Cách nghĩ sai: $x + y = 34$. Cách đúng: $2(x + y) = 34 \\Leftrightarrow x + y = 17$; $x - y = 7$."},{"de":"Tổ I vượt mức $10\\%$ so với kế hoạch $x$.","giai":"Thực tế tổ I làm $1{,}1x$ sản phẩm."}]'::jsonb, '[{"de":"Số lớn hơn số nhỏ $8$ ($x$ lớn, $y$ nhỏ)?","dapAn":"$x - y = 8$","giaiThich":"Hiệu bằng $8$.","dapAnGoc":"x − y = 8"},{"de":"Tổng hai số $50$?","dapAn":"$x + y = 50$","giaiThich":"Cộng.","dapAnGoc":"x + y = 50"}]'::jsonb),
  ('VBH-BTH-03', 'Mọi bài chuyển động đều quay về một công thức: $s = v\cdot t$.', '$s = v\cdot t$, $t = \dfrac{s}{v}$, $v = \dfrac{s}{t}$. Xuôi dòng: $v +$ vnước; ngược dòng: $v -$ vnước. Ngược chiều gặp nhau: tổng quãng đường $=$ khoảng cách ban đầu.', '[{"de":"Hai xe cách $180$ km đi ngược chiều, gặp nhau sau $2$ giờ.","giai":"Cách nghĩ sai: $x + y = 180$. Cách đúng: mỗi xe đi $2$ giờ: $2x + 2y = 180$."},{"de":"Xuôi $30$ km/h, ngược $24$ km/h.","giai":"$x + y = 30$, $x - y = 24$ nên vnước $= 3$ km/h."}]'::jsonb, '[{"de":"Đi $15$ km/h hết $2$ giờ được bao xa?","dapAn":"$30$ km","giaiThich":"$s = v\\cdot t$.","dapAnGoc":"30 km"},{"de":"Vận tốc riêng $20$, nước $3$, ngược dòng?","dapAn":"$17$ km/h","giaiThich":"$20 - 3$.","dapAnGoc":"17 km/h"}]'::jsonb),
  ('VBH-BTH-04', 'Hai người làm chung thì nhanh hơn — nên không thể cộng thời gian.', 'Làm xong việc trong $x$ đơn vị thời gian $\to$ mỗi đơn vị làm được $\dfrac{1}{x}$ công việc. Làm chung: cộng năng suất: $\dfrac{1}{x} + \dfrac{1}{y} = \dfrac{1}{t}$. Đổi $2$ giờ $24$ phút $= 2{,}4$ giờ $= \dfrac{12}{5}$ giờ.', '[{"de":"Vòi $A 4$ giờ, vòi $B 6$ giờ, cùng chảy?","giai":"Cách nghĩ sai: $4 + 6 = 10$ giờ. Cách đúng: $\\dfrac{1}{4} + \\dfrac{1}{6} = \\dfrac{5}{12}$ bể$/$giờ, đầy bể sau $\\dfrac{12}{5} = 2{,}4$ giờ."},{"de":"Cùng làm $12$ ngày xong việc.","giai":"Năng suất chung $\\dfrac{1}{12}$ công việc mỗi ngày."}]'::jsonb, '[{"de":"Làm xong trong $5$ ngày, mỗi ngày làm?","dapAn":"$\\dfrac{1}{5}$ công việc","giaiThich":"Năng suất.","dapAnGoc":"1/5 công việc"},{"de":"Hai đội $\\dfrac{1}{10}$ và $\\dfrac{1}{15}$ mỗi ngày, cùng làm?","dapAn":"$6$ ngày","giaiThich":"$\\dfrac{1}{10} + \\dfrac{1}{15} = \\dfrac{1}{6}$.","dapAnGoc":"6 ngày"}]'::jsonb)
on conflict (content_id) do update set dan = excluded.dan, quy_tac = excluded.quy_tac,
  vi_du = excluded.vi_du, tu_lam = excluded.tu_lam, updated_at = now();

