  ('C2-B4-M2', 'Bài 4. Phương trình quy về phương trình bậc nhất một ẩn', 'Mục 2. Phương trình chứa ẩn ở mẫu', 21, 'C2-B4-M1', true),
  ('C2-B5-M1', 'Bài 5. Bất đẳng thức và tính chất', 'Mục 1. Bất đẳng thức', 22, null, true),
  ('C2-B5-M2', 'Bài 5. Bất đẳng thức và tính chất', 'Mục 2. Tính chất của bất đẳng thức', 23, 'C2-B5-M1', true),
  ('C2-B6-M1', 'Bài 6. Bất phương trình bậc nhất một ẩn', 'Mục 1. Bất phương trình bậc nhất một ẩn', 24, 'C2-B5-M2', true),
  ('C2-B6-M2', 'Bài 6. Bất phương trình bậc nhất một ẩn', 'Mục 2. Giải bất phương trình bậc nhất một ẩn', 25, 'C2-B6-M1', true)
on conflict (ku_id) do update set lesson_id = excluded.lesson_id, ku_name = excluded.ku_name,
  order_index = excluded.order_index, prerequisite_ku = excluded.prerequisite_ku, co_video = excluded.co_video;

insert into contents (content_id, ku_id, kind, level, title, duration_sec, url, nguon) values
  ('VD-C2-B4-M1', 'C2-B4-M1', 'video', 2, 'Video bài học: Phương trình tích', 649, 'https://www.youtube.com/watch?v=Apwo51BP6-Y', 'OLM.VN — kênh YouTube @olm_vn, danh sách phát Toán lớp 9 mới (dùng lại, ghi nguồn)'),
