-- Link video: chỉ điền khi ô còn trống — link giáo viên đã tự gắn ở /gv/noi-dung được giữ nguyên.
on conflict (content_id) do update set title = excluded.title, ku_id = excluded.ku_id,
  duration_sec = case when contents.url is null or contents.url = '' then excluded.duration_sec else contents.duration_sec end,
  nguon = case when contents.url is null or contents.url = '' then excluded.nguon else contents.nguon end,
  url = case when contents.url is null or contents.url = '' then excluded.url else contents.url end;

insert into error_dictionary (error_code, ku_id, misconception, remediation_id) values
  ('E-PTT-01', 'C2-B4-M1', 'Giải phương trình tích chỉ lấy một nhân tử, dùng "và" thay "hoặc", hoặc chia hai vế cho biểu thức chứa ẩn nên mất nghiệm. Ví dụ: x(x − 4) = 0 chia cho x được x = 4', 'VBH-PTT-01'),
  ('E-PTT-02', 'C2-B4-M1', 'Áp dụng cách giải phương trình tích khi vế phải khác 0, hoặc chưa chuyển vế đưa về dạng tích bằng 0. Ví dụ: (x − 1)(x + 2) = 4 ⇒ x − 1 = 4 hoặc x + 2 = 4', 'VBH-PTT-02'),
  ('E-PTM-01', 'C2-B4-M2', 'Bỏ qua bước tìm điều kiện xác định, hoặc chỉ đặt điều kiện cho một mẫu, hoặc đặt sai dấu. Ví dụ: 1/(x − 2) + 3 = x/(x + 1): chỉ ghi x ≠ 2', 'VBH-PTM-01'),
  ('E-PTM-02', 'C2-B4-M2', 'Kết luận cả giá trị làm mẫu bằng 0 (hoặc trái điều kiện của bài toán thực tế) là nghiệm. Ví dụ: x/(x − 3) = 3/(x − 3) có nghiệm x = 3', 'VBH-PTM-02'),
  ('E-PTM-03', 'C2-B4-M2', 'Khử mẫu mà không nhân đủ các hạng tử với mẫu thức chung, hoặc nhân chéo khi có nhiều phân thức. Ví dụ: 1/x + 1/(x + 1) = 1 khử mẫu thành 1 + 1 = x(x + 1)', 'VBH-PTM-03'),
  ('E-BDT-01', 'C2-B5-M1', 'Nhầm dấu > với ≥, dịch "không nhỏ hơn", "tối đa", "tối thiểu" sai, hoặc so sánh hai số âm sai. Ví dụ: "a không nhỏ hơn b" viết a > b; −5 > −2', 'VBH-BDT-01'),
  ('E-BDT-02', 'C2-B5-M2', 'Nhân hoặc chia hai vế bất đẳng thức với số âm mà giữ nguyên chiều, hoặc đổi chiều cả khi cộng hay nhân với số dương. Ví dụ: a < b ⇒ −2a < −2b', 'VBH-BDT-02'),
  ('E-BDT-03', 'C2-B5-M2', 'Trừ vế với vế, nhân vế với vế hai bất đẳng thức khi không biết dấu, hoặc suy luận ngược chiều. Ví dụ: a > b, c > d ⇒ a − c > b − d; a > b ⇒ a² > b²', 'VBH-BDT-03'),
  ('E-BPT-01', 'C2-B6-M1', 'Nhận nhầm bất phương trình bậc nhất một ẩn (a = 0, có x²), kiểm tra nghiệm sai hoặc đếm nghiệm nguyên sai. Ví dụ: 0x + 3 > 0 là bất phương trình bậc nhất; x = 1,5 là nghiệm của 2x − 3 > 0', 'VBH-BPT-01'),
  ('E-BPT-02', 'C2-B6-M2', 'Chia hai vế cho số âm mà không đổi chiều, chuyển vế không đổi dấu, hoặc làm tròn nghiệm thực tế sai. Ví dụ: −2x > 6 ⇔ x > −3', 'VBH-BPT-02'),
  ('E-BPT-03', 'C2-B6-M2', 'Biểu diễn tập nghiệm trên trục số sai phía, dùng nhầm ngoặc tròn với ngoặc vuông. Ví dụ: x > 2 vẽ ngoặc vuông tại 2', 'VBH-BPT-03')
on conflict (error_code) do update set ku_id = excluded.ku_id, misconception = excluded.misconception,
  remediation_id = excluded.remediation_id;

insert into questions (question_id, ku_id, level, stem, correct_option, expected_time_sec, hinh, trang_thai, ghi_chu_gv, nguoi_duyet, ngay_duyet) values
  ('C2-B4-M1-Q01', 'C2-B4-M1', 1, 'Phương trình $(x - 2)(x + 3) = 0$ có các nghiệm là:', 'A', 45, null, 'nhap', null, null, null),
  ('C2-B4-M1-Q02', 'C2-B4-M1', 1, 'Phương trình $(ax + b)(cx + d) = 0$ tương đương với:', 'A', 45, null, 'nhap', null, null, null),
  ('C2-B4-M1-Q03', 'C2-B4-M1', 2, 'Nghiệm của phương trình $(2x - 1)(x + 5) = 0$ là:', 'A', 60, null, 'nhap', null, null, null),
  ('C2-B4-M1-Q04', 'C2-B4-M1', 2, 'Giải phương trình $x(x - 4) = 0$, bạn Nam chia hai vế cho $x$ được $x - 4 = 0$ nên $x = 4$. Nhận xét nào đúng?', 'A', 60, null, 'nhap', null, null, null),
  ('C2-B4-M1-Q05', 'C2-B4-M1', 3, 'Nghiệm của phương trình $x^{2} - 3x = 0$ là:', 'A', 90, null, 'nhap', null, null, null),
  ('C2-B4-M1-Q06', 'C2-B4-M1', 3, 'Cách giải nào đúng cho phương trình $(x - 1)(x + 2) = 4$?', 'A', 90, null, 'nhap', null, null, null),
  ('C2-B4-M1-Q07', 'C2-B4-M1', 4, 'Nghiệm của phương trình $(x + 3)(x - 1) = 2(x + 3)$ là:', 'A', 120, null, 'nhap', null, null, null),
  ('C2-B4-M1-Q08', 'C2-B4-M1', 4, 'Một mảnh vườn hình chữ nhật có chiều dài hơn chiều rộng $3$ m và diện tích $40$ m². Gọi chiều rộng là $x$ (m, $x > 0$). Phương trình và chiều rộng đúng là:', 'A', 120, null, 'nhap', null, null, null),
  ('C2-B4-M1-Q09', 'C2-B4-M1', 1, 'Nghiệm của phương trình $(x + 4)(x - 1) = 0$ là:', 'A', 45, null, 'nhap', null, null, null),
  ('C2-B4-M1-Q10', 'C2-B4-M1', 1, 'Nghiệm của phương trình $x(x + 7) = 0$ là:', 'A', 45, null, 'nhap', null, null, null),
  ('C2-B4-M1-Q11', 'C2-B4-M1', 2, 'Nghiệm của phương trình $(3x - 6)(2x + 1) = 0$ là:', 'A', 60, null, 'nhap', null, null, null),
  ('C2-B4-M1-Q12', 'C2-B4-M1', 2, 'Nghiệm của phương trình $x^{2} - 16 = 0$ là:', 'A', 60, null, 'nhap', null, null, null),
  ('C2-B4-M1-Q13', 'C2-B4-M1', 2, 'Đưa phương trình $x^{2} + 5x = 0$ về dạng phương trình tích, ta được:', 'A', 60, null, 'nhap', null, null, null),
  ('C2-B4-M1-Q14', 'C2-B4-M1', 3, 'Nghiệm của phương trình $2x(x - 3) + 5(x - 3) = 0$ là:', 'A', 90, null, 'nhap', null, null, null),
  ('C2-B4-M1-Q15', 'C2-B4-M1', 3, 'Nghiệm của phương trình $x^{2} - 4x + 4 = 0$ là:', 'A', 90, null, 'nhap', null, null, null),
  ('C2-B4-M1-Q16', 'C2-B4-M1', 4, 'Nghiệm của phương trình $(2x - 1)^{2} = (x + 3)^{2}$ là:', 'A', 120, null, 'nhap', null, null, null),
  ('C2-B4-M2-Q01', 'C2-B4-M2', 1, 'Điều kiện xác định của phương trình $1/(x - 2) + 3 = x/(x + 1)$ là:', 'A', 45, null, 'nhap', null, null, null),
  ('C2-B4-M2-Q02', 'C2-B4-M2', 1, 'Bước đầu tiên khi giải phương trình chứa ẩn ở mẫu là:', 'A', 45, null, 'nhap', null, null, null),
  ('C2-B4-M2-Q03', 'C2-B4-M2', 2, 'Điều kiện xác định của phương trình $\dfrac{2}{x} = 3/(x^{2} - 4)$ là:', 'A', 60, null, 'nhap', null, null, null),
  ('C2-B4-M2-Q04', 'C2-B4-M2', 2, 'Nghiệm của phương trình $(x + 1)/(x - 1) = 3$ là:', 'A', 60, null, 'nhap', null, null, null),
  ('C2-B4-M2-Q05', 'C2-B4-M2', 3, 'Phương trình $x/(x - 3) = 3/(x - 3)$:', 'A', 90, null, 'nhap', null, null, null),
  ('C2-B4-M2-Q06', 'C2-B4-M2', 3, 'Với $x \ne 0$ và $x \ne -1$, khử mẫu phương trình $\dfrac{1}{x} + 1/(x + 1) = 1$ ta được:', 'A', 90, null, 'nhap', null, null, null),
  ('C2-B4-M2-Q07', 'C2-B4-M2', 4, 'Nghiệm của phương trình $x/(x - 1) - 2/(x + 1) = 4/(x^{2} - 1)$ là:', 'A', 120, null, 'nhap', null, null, null),
  ('C2-B4-M2-Q08', 'C2-B4-M2', 4, 'Tổng của một số khác $0$ và nghịch đảo của nó bằng $\dfrac{5}{2}$. Số đó là:', 'A', 120, null, 'nhap', null, null, null),
  ('C2-B4-M2-Q09', 'C2-B4-M2', 1, 'Điều kiện xác định của phương trình $3/(x + 2) = 1$ là:', 'A', 45, null, 'nhap', null, null, null),
  ('C2-B4-M2-Q10', 'C2-B4-M2', 1, 'Điều kiện xác định của phương trình $x/(x - 5) + \dfrac{1}{x} = 2$ là:', 'A', 45, null, 'nhap', null, null, null),
  ('C2-B4-M2-Q11', 'C2-B4-M2', 2, 'Nghiệm của phương trình $2/(x - 1) = 1$ là:', 'A', 60, null, 'nhap', null, null, null),
  ('C2-B4-M2-Q12', 'C2-B4-M2', 2, 'Mẫu thức chung của các phân thức trong phương trình $1/(x - 2) + 3/(x + 2) = 4/(x^{2} - 4)$ là:', 'A', 60, null, 'nhap', null, null, null),
  ('C2-B4-M2-Q13', 'C2-B4-M2', 2, 'Giá trị $x = 2$ có thể là nghiệm của phương trình $1/(x - 2) + x = 3$ không?', 'A', 60, null, 'nhap', null, null, null),
  ('C2-B4-M2-Q14', 'C2-B4-M2', 3, 'Nghiệm của phương trình $(2x + 1)/(x - 3) = 3$ là:', 'A', 90, null, 'nhap', null, null, null),
  ('C2-B4-M2-Q15', 'C2-B4-M2', 3, 'Nghiệm của phương trình $(x^{2} - 1)/(x - 1) = 0$ là:', 'A', 90, null, 'nhap', null, null, null),
  ('C2-B4-M2-Q16', 'C2-B4-M2', 4, 'Nghiệm của phương trình $1/(x - 1) + 2/(x + 1) = 3/(x^{2} - 1)$ là:', 'A', 120, null, 'nhap', null, null, null),
  ('C2-B5-M1-Q01', 'C2-B5-M1', 1, '"$a$ không nhỏ hơn $b$" được viết là:', 'A', 45, null, 'nhap', null, null, null),
  ('C2-B5-M1-Q02', 'C2-B5-M1', 1, 'Bất đẳng thức nào đúng?', 'A', 45, null, 'nhap', null, null, null),
  ('C2-B5-M1-Q03', 'C2-B5-M1', 2, '"$x$ không vượt quá $10$" được viết là:', 'A', 60, null, 'nhap', null, null, null),
  ('C2-B5-M1-Q04', 'C2-B5-M1', 2, 'Với mọi số thực $a$, bất đẳng thức nào luôn đúng?', 'A', 60, null, 'nhap', null, null, null),
  ('C2-B5-M1-Q05', 'C2-B5-M1', 3, 'Biết $a - b = -3$. So sánh $a$ và $b$:', 'A', 90, null, 'nhap', null, null, null),
  ('C2-B5-M1-Q06', 'C2-B5-M1', 3, 'Một xe tải chở được tối đa $5$ tấn hàng. Gọi khối lượng hàng xe chở là $m$ (tấn). Ta có:', 'A', 90, null, 'nhap', null, null, null),
  ('C2-B5-M1-Q07', 'C2-B5-M1', 4, 'Cho $a > b$. Khẳng định nào chắc chắn đúng?', 'A', 120, null, 'nhap', null, null, null),
  ('C2-B5-M1-Q08', 'C2-B5-M1', 2, 'Biển báo trên đường cao tốc ghi "tốc độ tối thiểu $60$ km/h, tối đa $100$ km/h". Vận tốc $v$ (km/h) được phép thoả mãn:', 'A', 60, null, 'nhap', null, null, null),
  ('C2-B5-M1-Q09', 'C2-B5-M1', 1, '"$a$ không lớn hơn $b$" được viết là:', 'A', 45, null, 'nhap', null, null, null),
  ('C2-B5-M1-Q10', 'C2-B5-M1', 1, 'Bất đẳng thức nào đúng?', 'A', 45, null, 'nhap', null, null, null),
  ('C2-B5-M1-Q11', 'C2-B5-M1', 2, 'Số tiền tối thiểu để tham gia chuyến đi là $100 000$ đồng. Gọi $x$ là số tiền (đồng) một bạn mang theo để được tham gia. Ta có:', 'A', 60, null, 'nhap', null, null, null),
  ('C2-B5-M1-Q12', 'C2-B5-M1', 2, 'Cho $a = -2{,}5$ và $b = -2{,}3$. Khẳng định đúng là:', 'A', 60, null, 'nhap', null, null, null),
  ('C2-B5-M1-Q13', 'C2-B5-M1', 3, 'Cho $a \ge b$ và $b \ge a$. Khi đó:', 'A', 90, null, 'nhap', null, null, null),
  ('C2-B5-M1-Q14', 'C2-B5-M1', 3, 'Với mọi số thực $x$, bất đẳng thức nào luôn đúng?', 'A', 90, null, 'nhap', null, null, null),
  ('C2-B5-M1-Q15', 'C2-B5-M1', 4, 'Một thang máy chở tối đa $600$ kg. Trong thang có $8$ người, tổng khối lượng $560$ kg, mang thêm $x$ kg hàng. Điều kiện để thang máy chở được là:', 'A', 120, null, 'nhap', null, null, null),
  ('C2-B5-M1-Q16', 'C2-B5-M1', 4, 'Để chứng minh $a^{2} + b^{2} \ge 2ab$ với mọi $a$, $b$, ta dựa vào bất đẳng thức:', 'A', 120, null, 'nhap', null, null, null),
  ('C2-B5-M2-Q01', 'C2-B5-M2', 1, 'Cho $a < b$. Dấu thích hợp điền vào chỗ trống: $a + 5$ … $b + 5$ là', 'A', 45, null, 'nhap', null, null, null),
