insert into error_hints (error_code, tier, hint_text) values
  ('E-PTT-01', 1, 'Tích bằng $0$ khi nào: khi cả hai thừa số bằng $0$ hay chỉ cần một thừa số bằng $0$?'),
  ('E-PTT-01', 2, '$A\cdot B = 0 \Leftrightarrow A = 0$ hoặc $B = 0$. Giải từng phương trình bậc nhất rồi lấy tất cả nghiệm. Không chia hai vế cho biểu thức chứa ẩn vì có thể làm mất nghiệm.'),
  ('E-PTT-01', 3, 'Ví dụ: $x(x - 4) = 0 \Leftrightarrow x = 0$ hoặc $x = 4$; chia cho $x$ sẽ mất nghiệm $x = 0$.'),
  ('E-PTT-02', 1, 'Vế phải của phương trình đã bằng $0$ chưa? Nếu tích bằng $4$ thì mỗi thừa số có bắt buộc bằng $4$ không?'),
  ('E-PTT-02', 2, 'Chỉ khi tích bằng $0$ mới tách thành từng thừa số bằng $0$. Nếu vế phải khác $0$: chuyển hết sang một vế, rút gọn rồi phân tích thành nhân tử.'),
  ('E-PTT-02', 3, 'Ví dụ: $(x - 1)(x + 2) = 4 \Leftrightarrow x^{2} + x - 6 = 0 \Leftrightarrow (x - 2)(x + 3) = 0 \Leftrightarrow x = 2$ hoặc $x = -3$.'),
  ('E-PTM-01', 1, 'Phương trình có những mẫu nào chứa ẩn? Mỗi mẫu bằng $0$ khi $x$ bằng bao nhiêu?'),
  ('E-PTM-01', 2, 'Điều kiện xác định: mọi mẫu chứa ẩn đều khác $0$. Phân tích mẫu thành nhân tử $(x^{2} - 4 = (x - 2)(x + 2))$ để không bỏ sót.'),
  ('E-PTM-01', 3, 'Ví dụ: $1/(x - 2) + 3 = x/(x + 1)$ có điều kiện $x \ne 2$ và $x \ne -1$.'),
  ('E-PTM-02', 1, 'Giá trị vừa tìm có làm mẫu nào bằng $0$ không? Có hợp với điều kiện của bài toán không?'),
  ('E-PTM-02', 2, 'Giải xong phải đối chiếu điều kiện xác định (và điều kiện thực tế); giá trị nào vi phạm thì loại. Có thể phương trình vô nghiệm.'),
  ('E-PTM-02', 3, 'Ví dụ: $x/(x - 3) = 3/(x - 3)$ dẫn tới $x = 3$, nhưng $x \ne 3$ nên phương trình vô nghiệm.'),
  ('E-PTM-03', 1, 'Mẫu thức chung là gì? Em đã nhân nó với mọi hạng tử ở hai vế chưa?'),
  ('E-PTM-03', 2, 'Quy đồng mẫu hai vế bằng mẫu thức chung rồi khử mẫu: mỗi tử nhân với nhân tử phụ của nó; hạng tử không có mẫu nhân với cả mẫu thức chung.'),
  ('E-PTM-03', 3, 'Ví dụ: $\dfrac{1}{x} + 1/(x + 1) = 1$ (MTC $x(x + 1)$) $\Rightarrow (x + 1) + x = x(x + 1)$.'),
  ('E-BDT-01', 1, '"Không nhỏ hơn" nghĩa là lớn hơn, hay lớn hơn hoặc bằng?'),
  ('E-BDT-01', 2, '"Không nhỏ hơn", "tối thiểu" $\to \ge$; "không vượt quá", "tối đa" $\to \le$. Với số âm: số nào có giá trị tuyệt đối lớn hơn thì nhỏ hơn.'),
  ('E-BDT-01', 3, 'Ví dụ: "$a$ không nhỏ hơn $b$" là $a \ge b$; $-5 < -2$.'),
  ('E-BDT-02', 1, 'Em đang nhân hai vế với số dương hay số âm?'),
  ('E-BDT-02', 2, 'Cộng, trừ cùng một số: giữ chiều. Nhân, chia với số dương: giữ chiều. Nhân, chia với số âm: đổi chiều.'),
  ('E-BDT-02', 3, 'Ví dụ: $a < b \Rightarrow -2a > -2b$; $a < b \Rightarrow 2 - 5a > 2 - 5b$.'),
  ('E-BDT-03', 1, 'Hai bất đẳng thức có được trừ vế với vế không? Em đã biết dấu các số chưa?'),
  ('E-BDT-03', 2, 'Chỉ cộng vế với vế hai bất đẳng thức cùng chiều. Không trừ vế với vế; nhân vế với vế chỉ khi các vế đều dương. Bắc cầu: $a > b$ và $b > c$ thì $a > c$.'),
  ('E-BDT-03', 3, 'Ví dụ: $a > b$, $c > d \Rightarrow a + c > b + d$; với $a = -3 < b = -2$ thì $a^{2} = 9 > b^{2} = 4$.'),
  ('E-BPT-01', 1, 'Hệ số của $x$ có khác $0$ không? Thay số vào thì bất đẳng thức có đúng không?'),
  ('E-BPT-01', 2, 'Bất phương trình bậc nhất một ẩn có dạng $ax + b > 0$ (hoặc $<$, $\ge$, $\le$) với $a \ne 0$. Số $x_{0}$ là nghiệm nếu thay vào được bất đẳng thức đúng; dấu $>$ không chấp nhận bằng.'),
  ('E-BPT-01', 3, 'Ví dụ: $x = 1{,}5$ thay vào $2x - 3 > 0$ được $0 > 0$, sai, nên $1{,}5$ không là nghiệm.'),
  ('E-BPT-02', 1, 'Khi chia hai vế cho một số âm, chiều bất phương trình có giữ nguyên không?'),
  ('E-BPT-02', 2, 'Chuyển vế thì đổi dấu hạng tử. Nhân, chia hai vế cho số dương giữ chiều; cho số âm đổi chiều. Bài thực tế: lấy số nguyên lớn nhất (nhỏ nhất) thoả mãn.'),
  ('E-BPT-02', 3, 'Ví dụ: $-2x > 6 \Leftrightarrow x < -3$; $3 000x \le 50 000 \Leftrightarrow x \le 16{,}6$… nên mua nhiều nhất $16$ bút.'),
  ('E-BPT-03', 1, 'Điểm mút có thuộc tập nghiệm không? Tập nghiệm nằm bên trái hay bên phải điểm đó?'),
  ('E-BPT-03', 2, 'Dấu $>$ hoặc $<$ dùng ngoặc tròn (không lấy điểm mút); $\ge$ hoặc $\le$ dùng ngoặc vuông. $x > a$: phần bên phải; $x < a$: phần bên trái.'),
  ('E-BPT-03', 3, 'Ví dụ: $x > 2$ là phần bên phải điểm $2$ với ngoặc tròn "(" tại $2$; $x \le -5$ là bên trái $-5$ với ngoặc "]".')
on conflict (error_code, tier) do update set hint_text = excluded.hint_text;

insert into micro_lessons (content_id, dan, quy_tac, vi_du, tu_lam) values
  ('VBH-PTT-01', 'Tích bằng $0$ chỉ cần một thừa số bằng $0$ — nên phương trình tích thường có nhiều nghiệm.', '$A\cdot B = 0 \Leftrightarrow A = 0$ hoặc $B = 0$. Giải lần lượt từng phương trình rồi gom tất cả nghiệm. Không chia hai vế cho biểu thức chứa ẩn.', '[{"de":"Giải $x(x - 4) = 0$.","giai":"Cách nghĩ sai: chia cho $x$ được $x = 4$. Cách đúng: $x = 0$ hoặc $x - 4 = 0$, nghiệm $x = 0$; $x = 4$."},{"de":"Giải $(2x - 1)(x + 5) = 0$.","giai":"$2x - 1 = 0 \\Leftrightarrow x = \\dfrac{1}{2}$; $x + 5 = 0 \\Leftrightarrow x = -5$."}]'::jsonb, '[{"de":"Giải $(x - 2)(x + 3) = 0$.","dapAn":"$x = 2$; $x = -3$","giaiThich":"Mỗi thừa số bằng $0$.","dapAnGoc":"x = 2; x = −3"},{"de":"Giải $x^{2} - 3x = 0$.","dapAn":"$x = 0$; $x = 3$","giaiThich":"$x(x - 3) = 0$.","dapAnGoc":"x = 0; x = 3"}]'::jsonb),
  ('VBH-PTT-02', 'Cách tách "từng thừa số bằng $0$" chỉ dùng được khi vế phải là số $0$.', 'Nếu tích bằng một số khác $0$: chuyển hết về một vế, rút gọn, phân tích thành nhân tử rồi mới dùng $A\cdot B = 0$.', '[{"de":"Giải $(x - 1)(x + 2) = 4$.","giai":"Cách nghĩ sai: $x - 1 = 4$ hoặc $x + 2 = 4$. Cách đúng: $x^{2} + x - 6 = 0 \\Leftrightarrow (x - 2)(x + 3) = 0 \\Leftrightarrow x = 2$ hoặc $x = -3$."},{"de":"Giải $(x + 3)(x - 1) = 2(x + 3)$.","giai":"$(x + 3)(x - 1) - 2(x + 3) = 0 \\Leftrightarrow (x + 3)(x - 3) = 0 \\Leftrightarrow x = \\pm 3$."}]'::jsonb, '[{"de":"Giải $x(x + 1) = 2$.","dapAn":"$x = 1$; $x = -2$","giaiThich":"$x^{2} + x - 2 = 0 \\Leftrightarrow (x - 1)(x + 2) = 0$.","dapAnGoc":"x = 1; x = −2"},{"de":"Giải $(x - 2)^{2} = x - 2$.","dapAn":"$x = 2$; $x = 3$","giaiThich":"$(x - 2)(x - 3) = 0$.","dapAnGoc":"x = 2; x = 3"}]'::jsonb),
  ('VBH-PTM-01', 'Mẫu bằng $0$ thì phân thức vô nghĩa. Vì thế bước đầu tiên luôn là "cấm" các giá trị đó.', 'Điều kiện xác định: mọi mẫu chứa ẩn khác $0$. Phân tích mẫu thành nhân tử để tìm đủ các giá trị bị loại.', '[{"de":"Tìm ĐKXĐ của $1/(x - 2) + 3 = x/(x + 1)$.","giai":"Cách nghĩ sai: chỉ $x \\ne 2$. Cách đúng: $x - 2 \\ne 0$ và $x + 1 \\ne 0 \\Leftrightarrow x \\ne 2$ và $x \\ne -1$."},{"de":"Tìm ĐKXĐ của $\\dfrac{2}{x} = 3/(x^{2} - 4)$.","giai":"$x \\ne 0$ và $(x - 2)(x + 2) \\ne 0 \\Leftrightarrow x \\ne 0$; $x \\ne \\pm 2$."}]'::jsonb, '[{"de":"ĐKXĐ của $5/(2x - 6)$?","dapAn":"$x \\ne 3$","giaiThich":"$2x - 6 \\ne 0$.","dapAnGoc":"x ≠ 3"},{"de":"ĐKXĐ của $1/(x^{2} - 1)$?","dapAn":"$x \\ne \\pm 1$","giaiThich":"$x^{2} - 1 = (x - 1)(x + 1)$.","dapAnGoc":"x ≠ ±1"}]'::jsonb),
  ('VBH-PTM-02', 'Giải ra $x$ chưa phải là xong: còn bước "soát vé" với điều kiện.', 'Sau khi giải phương trình đã khử mẫu, loại các giá trị vi phạm điều kiện xác định (và điều kiện thực tế). Không còn giá trị nào thì phương trình vô nghiệm.', '[{"de":"Giải $x/(x - 3) = 3/(x - 3)$.","giai":"Cách nghĩ sai: $x = 3$ là nghiệm. Cách đúng: ĐKXĐ $x \\ne 3$; khử mẫu được $x = 3$, bị loại, phương trình vô nghiệm."},{"de":"Chiều rộng $x > 0$ thoả $x(x + 3) = 40$.","giai":"$x = 5$ hoặc $x = -8$; loại $-8$ vì $x > 0$, chiều rộng $5$ m."}]'::jsonb, '[{"de":"ĐKXĐ $x \\ne 1$, giải được $x = 1$ và $x = 2$. Nghiệm?","dapAn":"$x = 2$","giaiThich":"Loại $x = 1$.","dapAnGoc":"x = 2"},{"de":"ĐKXĐ $x \\ne \\pm 1$, giải được $x = -1$. Kết luận?","dapAn":"Vô nghiệm","giaiThich":"Giá trị duy nhất bị loại.","dapAnGoc":"Vô nghiệm"}]'::jsonb),
  ('VBH-PTM-03', 'Khử mẫu giống "nhân cả nhà" với mẫu thức chung: không được sót hạng tử nào.', 'Tìm mẫu thức chung (MTC), quy đồng hai vế, rồi khử mẫu: mỗi tử nhân với nhân tử phụ; hạng tử không có mẫu nhân với cả MTC.', '[{"de":"Khử mẫu $\\dfrac{1}{x} + 1/(x + 1) = 1$.","giai":"Cách nghĩ sai: $1 + 1 = x(x + 1)$. Cách đúng: MTC $x(x + 1)$: $(x + 1) + x = x(x + 1)$."},{"de":"Giải $(x + 1)/(x - 1) = 3$.","giai":"$x + 1 = 3(x - 1) \\Leftrightarrow x = 2$ (thoả $x \\ne 1$)."}]'::jsonb, '[{"de":"Khử mẫu $\\dfrac{x}{2} + \\dfrac{1}{3} = 1$.","dapAn":"$3x + 2 = 6$","giaiThich":"MTC $6$.","dapAnGoc":"3x + 2 = 6"},{"de":"Giải $\\dfrac{2}{x} = 1$.","dapAn":"$x = 2$","giaiThich":"$x \\ne 0$; $2 = x$.","dapAnGoc":"x = 2"}]'::jsonb),
  ('VBH-BDT-01', 'Mỗi cụm từ trong lời văn ứng với đúng một dấu. Đọc đúng là viết đúng.', '"Lớn hơn" $>$, "nhỏ hơn" $<$, "không nhỏ hơn $/$ tối thiểu $/$ ít nhất" $\ge$, "không lớn hơn $/$ không vượt quá $/$ tối đa" $\le$. Với hai số âm, số có giá trị tuyệt đối lớn hơn thì nhỏ hơn.', '[{"de":"Viết \"$a$ không nhỏ hơn $b$\".","giai":"Cách nghĩ sai: $a > b$. Cách đúng: $a \\ge b$ ($a$ lớn hơn hoặc bằng $b$)."},{"de":"So sánh $-5$ và $-2$.","giai":"$-5$ nằm bên trái $-2$ trên trục số nên $-5 < -2$."}]'::jsonb, '[{"de":"\"Tối đa $5$ tấn\" với $m$?","dapAn":"$m \\le 5$","giaiThich":"Không vượt quá.","dapAnGoc":"m ≤ 5"},{"de":"$a - b = -3$ thì?","dapAn":"$a < b$","giaiThich":"Hiệu âm.","dapAnGoc":"a < b"}]'::jsonb),
  ('VBH-BDT-02', 'Có đúng một phép làm bất đẳng thức "lộn chiều": nhân hoặc chia với số âm.', '$a < b \Rightarrow a + c < b + c$ (mọi $c$). $a < b$, $c > 0 \Rightarrow ac < bc$. $a < b$, $c < 0 \Rightarrow ac > bc$ (đổi chiều).', '[{"de":"Cho $a < b$, so sánh $-2a$ và $-2b$.","giai":"Cách nghĩ sai: $-2a < -2b$. Cách đúng: nhân với $-2 < 0$ nên đổi chiều: $-2a > -2b$."},{"de":"Cho $a < b$, so sánh $3a - 1$ và $3b - 1$.","giai":"Nhân $3 > 0$ giữ chiều rồi trừ $1$: $3a - 1 < 3b - 1$."}]'::jsonb, '[{"de":"$a > b$ thì $-a$ … $-b$?","dapAn":"$<$","giaiThich":"Nhân $-1$.","dapAnGoc":"<"},{"de":"$a < b$ thì $\\dfrac{a}{4}$ … $\\dfrac{b}{4}$?","dapAn":"$<$","giaiThich":"Chia số dương.","dapAnGoc":"<"}]'::jsonb),
  ('VBH-BDT-03', 'Hai bất đẳng thức chỉ "cộng" được với nhau. Trừ hay nhân thì phải rất cẩn thận.', '$a > b$ và $c > d \Rightarrow a + c > b + d$. Không có quy tắc trừ vế với vế. Nhân vế với vế chỉ đúng khi các vế đều dương. Muốn chứng minh, đi từ giả thiết đến kết luận.', '[{"de":"$a > b$, $c > d$ có suy ra $a - c > b - d$?","giai":"Cách nghĩ sai: có. Phản ví dụ: $5 > 1$, $10 > 0$ nhưng $5 - 10 = -5 < 1 - 0 = 1$."},{"de":"$a < b < 0$, so sánh $a^{2}$ và $b^{2}$.","giai":"Ví dụ $a = -3$, $b = -2$: $9 > 4$. Thật vậy $a^{2} - b^{2} = (a - b)(a + b) > 0$ vì cả hai thừa số âm."}]'::jsonb, '[{"de":"$3 > 1$ và $2 > 0$ thì $3 + 2$ … $1 + 0$?","dapAn":"$>$","giaiThich":"Cộng vế với vế.","dapAnGoc":">"},{"de":"$a > b$ có suy ra $a^{2} > b^{2}$ với mọi $a$, $b$?","dapAn":"Không","giaiThich":"$a = 1$, $b = -2$.","dapAnGoc":"Không"}]'::jsonb),
  ('VBH-BPT-01', 'Bất phương trình bậc nhất một ẩn: giống phương trình bậc nhất, chỉ thay dấu "$=$" bằng dấu so sánh.', 'Dạng $ax + b > 0$ (hoặc $<$, $\ge$, $\le$) với $a \ne 0$. Số $x_{0}$ là nghiệm nếu thay vào được bất đẳng thức đúng. Dấu $>$ không nhận trường hợp bằng.', '[{"de":"$x = 1{,}5$ có là nghiệm của $2x - 3 > 0$?","giai":"Cách nghĩ sai: có. Cách đúng: $2\\cdot 1{,}5 - 3 = 0$ và $0 > 0$ sai, nên không."},{"de":"$0x + 3 > 0$ có phải bất phương trình bậc nhất một ẩn?","giai":"Không vì $a = 0$."}]'::jsonb, '[{"de":"$x = 2$ có là nghiệm của $2x - 3 > 0$?","dapAn":"Có","giaiThich":"$1 > 0$.","dapAnGoc":"Có"},{"de":"Nghiệm nguyên dương của $x \\le 2$?","dapAn":"$1$; $2$","giaiThich":"Số nguyên dương nhỏ hơn hoặc bằng $2$.","dapAnGoc":"1; 2"}]'::jsonb),
  ('VBH-BPT-02', 'Giải bất phương trình như giải phương trình — trừ một chỗ: chia cho số âm.', 'Chuyển vế: đổi dấu hạng tử. Chia hai vế cho $a > 0$: giữ chiều; cho $a < 0$: đổi chiều. Bài thực tế: chọn số nguyên phù hợp.', '[{"de":"Giải $-2x > 6$.","giai":"Cách nghĩ sai: $x > -3$. Cách đúng: chia cho $-2 < 0$, đổi chiều: $x < -3$."},{"de":"Giải $5 - 2x \\ge 1$.","giai":"$-2x \\ge -4 \\Leftrightarrow x \\le 2$."}]'::jsonb, '[{"de":"Giải $x - 3 > 2$.","dapAn":"$x > 5$","giaiThich":"Chuyển vế.","dapAnGoc":"x > 5"},{"de":"Giải $3x + 4 \\le 2x - 1$.","dapAn":"$x \\le -5$","giaiThich":"Chuyển vế.","dapAnGoc":"x ≤ −5"}]'::jsonb),
  ('VBH-BPT-03', 'Trục số giúp "nhìn thấy" tập nghiệm — nhưng ngoặc và phía phải đúng.', '$>$ hoặc $<$: ngoặc tròn, không lấy điểm mút. $\ge$ hoặc $\le$: ngoặc vuông, lấy điểm mút. $x > a$: phía phải $a$; $x < a$: phía trái $a$.', '[{"de":"Biểu diễn $x > 2$.","giai":"Cách nghĩ sai: ngoặc vuông tại $2$. Cách đúng: ngoặc tròn \"(\" tại $2$, gạch bỏ phần bên trái."},{"de":"Biểu diễn $x \\le -5$.","giai":"Ngoặc vuông \"]\" tại $-5$, lấy phần bên trái."}]'::jsonb, '[{"de":"$x \\ge 1$ dùng ngoặc nào tại $1$?","dapAn":"[","giaiThich":"Lấy điểm $1$.","dapAnGoc":"["},{"de":"$x < 0$ lấy phía nào?","dapAn":"Bên trái $0$","giaiThich":"Nhỏ hơn $0$.","dapAnGoc":"Bên trái 0"}]'::jsonb)
on conflict (content_id) do update set dan = excluded.dan, quy_tac = excluded.quy_tac,
  vi_du = excluded.vi_du, tu_lam = excluded.tu_lam, updated_at = now();

