insert into knowledge_units (ku_id, lesson_id, ku_name, order_index, prerequisite_ku, co_video) values
  ('C3-B7-M1', 'Bài 7. Căn bậc hai và căn thức bậc hai', 'Mục 1. Căn bậc hai của số thực không âm', 30, null, true),
  ('C3-B7-M2', 'Bài 7. Căn bậc hai và căn thức bậc hai', 'Mục 2. Căn thức bậc hai', 31, 'C3-B7-M1', true),
  ('C3-B8-M1', 'Bài 8. Khai căn bậc hai với phép nhân và phép chia', 'Mục 1. Khai căn bậc hai với phép nhân', 32, 'C3-B7-M2', true),
  ('C3-B8-M2', 'Bài 8. Khai căn bậc hai với phép nhân và phép chia', 'Mục 2. Khai căn bậc hai với phép chia', 33, 'C3-B8-M1', true),
  ('C3-B9-M1', 'Bài 9. Biến đổi đơn giản và rút gọn biểu thức chứa căn thức bậc hai', 'Mục 1. Đưa thừa số ra ngoài dấu căn', 34, 'C3-B8-M2', true),
  ('C3-B9-M1B', 'Bài 9. Biến đổi đơn giản và rút gọn biểu thức chứa căn thức bậc hai', 'Mục 2. Đưa thừa số vào trong dấu căn', 35, 'C3-B9-M1', true),
  ('C3-B9-M2', 'Bài 9. Biến đổi đơn giản và rút gọn biểu thức chứa căn thức bậc hai', 'Mục 3. Trục căn thức ở mẫu (mẫu chứa một căn thức)', 36, 'C3-B9-M1B', true),
  ('C3-B9-M2B', 'Bài 9. Biến đổi đơn giản và rút gọn biểu thức chứa căn thức bậc hai', 'Mục 3 (tiếp). Trục căn thức ở mẫu (mẫu chứa hai căn thức)', 37, 'C3-B9-M2', true),
  ('C3-B9-M3', 'Bài 9. Biến đổi đơn giản và rút gọn biểu thức chứa căn thức bậc hai', 'Mục 4. Rút gọn biểu thức chứa căn thức bậc hai', 38, 'C3-B9-M2B', true),
  ('C3-B10-M1', 'Bài 10. Căn bậc ba và căn thức bậc ba', 'Mục 1. Căn bậc ba của số thực', 39, 'C3-B7-M1', true),
  ('C3-B10-M2', 'Bài 10. Căn bậc ba và căn thức bậc ba', 'Mục 2. Căn thức bậc ba', 40, 'C3-B10-M1', true),
  ('C3-LTC', 'Luyện tập chung và Bài tập cuối chương III', 'Luyện tập chung Chương III', 41, 'C3-B10-M2', false)
on conflict (ku_id) do update set lesson_id = excluded.lesson_id, ku_name = excluded.ku_name,
  order_index = excluded.order_index, prerequisite_ku = excluded.prerequisite_ku, co_video = excluded.co_video;

