-- Link video: chỉ điền khi ô còn trống — link giáo viên đã tự gắn ở /gv/noi-dung được giữ nguyên.
on conflict (content_id) do update set title = excluded.title, ku_id = excluded.ku_id,
  duration_sec = case when contents.url is null or contents.url = '' then excluded.duration_sec else contents.duration_sec end,
  nguon = case when contents.url is null or contents.url = '' then excluded.nguon else contents.nguon end,
  url = case when contents.url is null or contents.url = '' then excluded.url else contents.url end;

insert into error_dictionary (error_code, ku_id, misconception, remediation_id) values
  ('E-CBH-01', 'C3-B7-M1', 'Nhầm căn bậc hai với căn bậc hai số học: cho rằng 16 chỉ có một căn bậc hai là 4, hoặc viết √16 = ±4. Ví dụ: √25 = ±5; căn bậc hai của 16 chỉ là 4', 'VBH-CBH-01'),
  ('E-CBH-02', 'C3-B7-M1', 'Cho rằng số âm có căn bậc hai (khai căn số âm ra số âm). Ví dụ: √(−9) = −3', 'VBH-CBH-02'),
  ('E-CBH-03', 'C3-B7-M2', 'Tìm điều kiện xác định của căn thức sai: lấy A > 0 thay vì A ≥ 0, quên điều kiện mẫu khác 0, hoặc cho căn thức xác định với mọi x. Ví dụ: √(x − 3) xác định khi x > 3', 'VBH-CBH-03'),
  ('E-CBH-04', 'C3-B7-M2', 'Viết √(A²) = A mà không lấy giá trị tuyệt đối, nên sai khi A âm. Ví dụ: √((−5)²) = −5; √((2 − √5)²) = 2 − √5', 'VBH-CBH-04'),
  ('E-CBH-05', 'C3-B7-M1', 'So sánh các căn bậc hai, số với căn sai chiều (nhất là với số âm), hoặc không đưa về cùng dạng để so sánh. Ví dụ: −√5 > −√3 vì 5 > 3; 4 < √15', 'VBH-CBH-05'),
  ('E-KC-01', 'C3-B8-M1', 'Tách căn bậc hai của một tổng (hiệu) thành tổng (hiệu) các căn, hoặc cộng các căn thành căn của tổng. Ví dụ: √(9 + 16) = 3 + 4 = 7; √2 + √3 = √5', 'VBH-KC-01'),
  ('E-KC-02', 'C3-B8-M1', 'Áp dụng √(A·B) = √A · √B cả khi A, B âm, dẫn đến căn của số âm hoặc kết luận "không tính được". Ví dụ: √((−4)(−9)) = √(−4) · √(−9), không tính được', 'VBH-KC-02'),
  ('E-KC-03', 'C3-B8-M2', 'Khai căn một thương chỉ khai căn tử (hoặc mẫu), hoặc quên điều kiện mẫu dương. Ví dụ: √(9/4) = √9 / 4 = 3/4', 'VBH-KC-03'),
  ('E-BD-01', 'C3-B9-M1', 'Đưa thừa số ra ngoài dấu căn sai: đưa ra số không phải bình phương, quên lấy căn của thừa số, quên giá trị tuyệt đối khi thừa số âm. Ví dụ: √18 = 9√2; √(9x²y) = 3x√y với x < 0', 'VBH-BD-01'),
  ('E-BD-02', 'C3-B9-M1B', 'Đưa thừa số vào trong dấu căn quên bình phương thừa số, hoặc đưa cả dấu "−" vào trong căn. Ví dụ: 2√3 = √6; −2√3 = √12', 'VBH-BD-02'),
  ('E-BD-03', 'C3-B9-M2', 'Trục căn thức ở mẫu nhân với chính mẫu thay vì biểu thức liên hợp, hoặc chỉ nhân mẫu mà không nhân tử. Ví dụ: 1/(√5 − 2): nhân cả tử và mẫu với √5 − 2', 'VBH-BD-03'),
  ('E-BD-04', 'C3-B9-M2B', 'Tính tích (√a + √b)(√a − √b) hoặc bình phương tổng có căn sai: ra a + b, a² − b², hoặc quên hạng tử 2√ab. Ví dụ: (√6 + √2)(√6 − √2) = 6² − 2² = 32; (√3 + 1)² = 4', 'VBH-BD-04'),
  ('E-BD-05', 'C3-B9-M3', 'Rút gọn biểu thức chứa căn mà cộng các căn không đồng dạng, rút gọn chưa triệt để hoặc bỏ qua điều kiện xác định. Ví dụ: √20 − √45 + √5 = √(−20)', 'VBH-BD-05'),
  ('E-CBB-01', 'C3-B10-M1', 'Nhầm căn bậc ba với căn bậc hai: cho rằng số âm không có căn bậc ba, hoặc căn bậc ba có hai giá trị ±. Ví dụ: ∛(−8) không xác định; ∛8 = ±2', 'VBH-CBB-01'),
  ('E-CBB-02', 'C3-B10-M2', 'Đặt điều kiện A ≥ 0 cho căn thức bậc ba, hoặc viết ∛(A³) = |A|. Ví dụ: ∛(x − 2) xác định khi x ≥ 2; ∛((−3)³) = 3', 'VBH-CBB-02')
on conflict (error_code) do update set ku_id = excluded.ku_id, misconception = excluded.misconception,
  remediation_id = excluded.remediation_id;

