insert into error_hints (error_code, tier, hint_text) values
  ('E-CBH-01', 1, 'Số nào bình phương lên bằng $16$? Có mấy số như vậy?'),
  ('E-CBH-01', 2, 'Số dương $a$ có hai căn bậc hai đối nhau: $\sqrt{a}$ (dương, gọi là căn bậc hai số học) và $-\sqrt{a}$. Kí hiệu $\sqrt{a}$ chỉ số không âm.'),
  ('E-CBH-01', 3, 'Ví dụ: $16$ có hai căn bậc hai là $4$ và $-4$; còn $\sqrt{16} = 4$ (không viết $\pm 4$).'),
  ('E-CBH-02', 1, 'Có số nào bình phương lên ra số âm không?'),
  ('E-CBH-02', 2, 'Bình phương của mọi số đều không âm, nên số âm không có căn bậc hai. $\sqrt{-9}$ không xác định.'),
  ('E-CBH-02', 3, 'Ví dụ: $3^{2} = 9$ và $(-3)^{2} = 9$, không có số nào bình phương bằng $-9$.'),
  ('E-CBH-03', 1, 'Biểu thức dưới dấu căn được phép bằng $0$ không? Có mẫu số không?'),
  ('E-CBH-03', 2, '$\sqrt{A}$ xác định khi $A \ge 0$ (được bằng $0$). Nếu căn nằm ở mẫu thì thêm điều kiện mẫu khác $0$, tức $A > 0$.'),
  ('E-CBH-03', 3, 'Ví dụ: $\sqrt{x - 3}$ xác định khi $x - 3 \ge 0 \Leftrightarrow x \ge 3$; còn $1/\sqrt{x - 1}$ cần $x - 1 > 0 \Leftrightarrow x > 1$.'),
  ('E-CBH-04', 1, 'Biểu thức trong ngoặc mang dấu âm hay dương?'),
  ('E-CBH-04', 2, '$\sqrt{A^{2}} = |A|$: bằng $A$ khi $A \ge 0$ và bằng $-A$ khi $A < 0$. Kết quả của căn bậc hai số học luôn không âm.'),
  ('E-CBH-04', 3, 'Ví dụ: $\sqrt{(-5)^{2}} = |-5| = 5$; $\sqrt{(2 - \sqrt{5})^{2}} = |2 - \sqrt{5}| = \sqrt{5} - 2$ vì $2 < \sqrt{5}$.'),
  ('E-CBH-05', 1, 'Nếu bình phương hai số (đều không âm) thì số nào lớn hơn?'),
  ('E-CBH-05', 2, 'Với $a$, $b \ge 0$: $a < b \Leftrightarrow \sqrt{a} < \sqrt{b}$. Muốn so sánh số với căn, viết số đó thành căn $(4 = \sqrt{16})$. Với số âm, chiều so sánh đổi ngược.'),
  ('E-CBH-05', 3, 'Ví dụ: $4 = \sqrt{16} > \sqrt{15}$. Còn $-\sqrt{5} < -\sqrt{3}$ vì $\sqrt{5} > \sqrt{3}$.'),
  ('E-KC-01', 1, 'Quy tắc khai căn áp dụng cho tích hay cho tổng?'),
  ('E-KC-01', 2, 'Chỉ có $\sqrt{A\cdot B} = \sqrt{A} \cdot \sqrt{B}$ (và với thương). Không có quy tắc cho tổng, hiệu: $\sqrt{a + b} \ne \sqrt{a} + \sqrt{b}$. Phải tính tổng dưới căn trước.'),
  ('E-KC-01', 3, 'Ví dụ: $\sqrt{9 + 16} = \sqrt{25} = 5$, không phải $3 + 4 = 7$.'),
  ('E-KC-02', 1, 'Các thừa số dưới căn có âm không? Em đã tính tích của chúng chưa?'),
  ('E-KC-02', 2, 'Quy tắc $\sqrt{A\cdot B} = \sqrt{A} \cdot \sqrt{B}$ chỉ dùng khi $A$, $B \ge 0$. Nếu các thừa số âm thì tính tích trước (tích hai số âm là số dương).'),
  ('E-KC-02', 3, 'Ví dụ: $\sqrt{(-4)(-9)} = \sqrt{36} = 6$, không viết $\sqrt{-4} \cdot \sqrt{-9}$.'),
  ('E-KC-03', 1, 'Em đã khai căn cả tử và mẫu chưa?'),
  ('E-KC-03', 2, '$\sqrt{\dfrac{A}{B}} = \sqrt{A} / \sqrt{B}$ với $A \ge 0$, $B > 0$: khai căn tử và khai căn mẫu.'),
  ('E-KC-03', 3, 'Ví dụ: $\sqrt{\dfrac{9}{4}} = \sqrt{9} / \sqrt{4} = \dfrac{3}{2}$; $\sqrt{50} : \sqrt{2} = \sqrt{25} = 5$.'),
  ('E-BD-01', 1, 'Trong số dưới dấu căn có thừa số nào là số chính phương không? Thừa số đưa ra có thể âm không?'),
  ('E-BD-01', 2, '$\sqrt{A^{2}B} = |A|\sqrt{B} (B \ge 0)$: tách số dưới căn thành (số chính phương) $\times$ (phần còn lại), đưa căn của số chính phương ra ngoài; nếu $A$ âm thì lấy $|A|$.'),
  ('E-BD-01', 3, 'Ví dụ: $\sqrt{18} = \sqrt{9 \cdot 2} = 3\sqrt{2}$; với $x < 0$: $\sqrt{9x^{2}y} = 3|x|\sqrt{y} = -3x\sqrt{y}$.'),
  ('E-BD-02', 1, 'Khi đưa số vào trong căn, số đó phải biến thành gì? Dấu "$-$" đi đâu?'),
  ('E-BD-02', 2, '$A\sqrt{B} = \sqrt{A^{2}B}$ khi $A \ge 0$; $A\sqrt{B} = -\sqrt{A^{2}B}$ khi $A < 0$. Bình phương thừa số khi đưa vào; dấu "$-$" giữ ở ngoài căn.'),
  ('E-BD-02', 3, 'Ví dụ: $2\sqrt{3} = \sqrt{4 \cdot 3} = \sqrt{12}$; $-2\sqrt{3} = -\sqrt{12}$.'),
  ('E-BD-03', 1, 'Nhân với biểu thức nào thì mẫu hết căn?'),
  ('E-BD-03', 2, 'Mẫu $\sqrt{b}$: nhân cả tử và mẫu với $\sqrt{b}$. Mẫu $\sqrt{b} \pm c$: nhân cả tử và mẫu với biểu thức liên hợp $\sqrt{b} \mp c$ (đổi dấu ở giữa).'),
  ('E-BD-03', 3, 'Ví dụ: $1/(\sqrt{5} - 2) = (\sqrt{5} + 2)/((\sqrt{5})^{2} - 2^{2}) = (\sqrt{5} + 2)/1 = \sqrt{5} + 2$.'),
  ('E-BD-04', 1, '$(x + y)(x - y)$ bằng bao nhiêu? Ở đây $x = \sqrt{a}$ thì $x^{2}$ bằng gì?'),
  ('E-BD-04', 2, '$(\sqrt{a} + \sqrt{b})(\sqrt{a} - \sqrt{b}) = (\sqrt{a})^{2} - (\sqrt{b})^{2} = a - b$. Còn $(\sqrt{a} + b)^{2} = a + 2b\sqrt{a} + b^{2}$ — đừng quên hạng tử giữa.'),
  ('E-BD-04', 3, 'Ví dụ: $(\sqrt{6} + \sqrt{2})(\sqrt{6} - \sqrt{2}) = 6 - 2 = 4$; $(\sqrt{3} + 1)^{2} = 3 + 2\sqrt{3} + 1 = 4 + 2\sqrt{3}$.'),
  ('E-BD-05', 1, 'Các căn em đang cộng có cùng biểu thức dưới dấu căn không?'),
  ('E-BD-05', 2, 'Đưa các căn về dạng $a\sqrt{b}$ ($b$ nhỏ nhất), rồi chỉ cộng, trừ các căn đồng dạng (cùng $\sqrt{b}$). $\sqrt{2} + \sqrt{3}$ không gộp được.'),
  ('E-BD-05', 3, 'Ví dụ: $\sqrt{20} - \sqrt{45} + \sqrt{5} = 2\sqrt{5} - 3\sqrt{5} + \sqrt{5} = 0$.'),
  ('E-CBB-01', 1, 'Số nào lập phương lên bằng $-8$? Số đó âm hay dương?'),
  ('E-CBB-01', 2, 'Mọi số thực đều có đúng một căn bậc ba; căn bậc ba của số âm là số âm, của số dương là số dương.'),
  ('E-CBB-01', 3, 'Ví dụ: $\sqrt[3]{-8} = -2$ vì $(-2)^{3} = -8$; $\sqrt[3]{27} = 3$ (không phải $\pm 3$).'),
  ('E-CBB-02', 1, 'Căn bậc ba có cần biểu thức dưới căn không âm không?'),
  ('E-CBB-02', 2, '$\sqrt[3]{A}$ xác định khi $A$ xác định (không cần $A \ge 0$). $\sqrt[3]{A^{3}} = A$ (không lấy giá trị tuyệt đối).'),
  ('E-CBB-02', 3, 'Ví dụ: $\sqrt[3]{x - 2}$ xác định với mọi $x$; $\sqrt[3]{(-3)^{3}} = -3$.')
on conflict (error_code, tier) do update set hint_text = excluded.hint_text;

insert into micro_lessons (content_id, dan, quy_tac, vi_du, tu_lam) values
  ('VBH-CBH-01', '"Căn bậc hai của $16$" và "$\sqrt{16}$" nghe giống nhau nhưng là hai câu hỏi khác nhau.', 'Căn bậc hai của số $a \ge 0$ là số $x$ mà $x^{2} = a$. Số dương $a$ có hai căn bậc hai đối nhau: $\sqrt{a}$ (căn bậc hai số học, không âm) và $-\sqrt{a}$. Kí hiệu $\sqrt{a}$ luôn chỉ một số không âm.', '[{"de":"Tìm các căn bậc hai của $16$ và tính $\\sqrt{16}$.","giai":"Cách nghĩ sai: căn bậc hai của $16$ chỉ là $4$, còn $\\sqrt{16} = \\pm 4$. Cách đúng: $16$ có hai căn bậc hai là $4$ và $-4$; $\\sqrt{16} = 4$."},{"de":"Tính $\\sqrt{0{,}49}$.","giai":"$0{,}7^{2} = 0{,}49$ và $0{,}7 \\ge 0$ nên $\\sqrt{0{,}49} = 0{,}7$."}]'::jsonb, '[{"de":"Các căn bậc hai của $81$?","dapAn":"$9$ và $-9$","giaiThich":"$9^{2} = (-9)^{2} = 81$.","dapAnGoc":"9 và −9"},{"de":"$\\sqrt{36}$ bằng?","dapAn":"$6$","giaiThich":"Căn bậc hai số học không âm.","dapAnGoc":"6"}]'::jsonb),
  ('VBH-CBH-02', 'Có một loại số không có căn bậc hai — và đó là chỗ hay bị quên.', 'Bình phương của mọi số thực đều không âm. Vì vậy số âm không có căn bậc hai; $\sqrt{a}$ chỉ có nghĩa khi $a \ge 0$.', '[{"de":"Tính $\\sqrt{-9}$.","giai":"Cách nghĩ sai: $\\sqrt{-9} = -3$. Cách đúng: $(-3)^{2} = 9$, không phải $-9$; không có số nào bình phương bằng $-9$, nên $\\sqrt{-9}$ không xác định."},{"de":"Số $0$ có căn bậc hai không?","giai":"Có đúng một căn bậc hai là $0$."}]'::jsonb, '[{"de":"$-25$ có căn bậc hai không?","dapAn":"Không","giaiThich":"Số âm.","dapAnGoc":"Không"},{"de":"$\\sqrt{0}$ bằng?","dapAn":"$0$","giaiThich":"$0^{2} = 0$.","dapAnGoc":"0"}]'::jsonb),
  ('VBH-CBH-03', 'Điều kiện xác định là "giấy phép" để căn thức có nghĩa. Thiếu dấu bằng hay quên mẫu số là sai cả bài.', '$\sqrt{A}$ xác định khi $A \ge 0$. Nếu căn thức nằm ở mẫu thì cần thêm mẫu khác $0$, tức $A > 0$. Giải bất phương trình để tìm $x$.', '[{"de":"Tìm điều kiện xác định của $\\sqrt{x - 3}$.","giai":"Cách nghĩ sai: $x > 3$. Cách đúng: $x - 3 \\ge 0 \\Leftrightarrow x \\ge 3$ ($x = 3$ cho $\\sqrt{0} = 0$, vẫn xác định)."},{"de":"Tìm điều kiện xác định của $1/\\sqrt{x - 1}$.","giai":"Cần $x - 1 \\ge 0$ và $\\sqrt{x - 1} \\ne 0$, tức $x - 1 > 0 \\Leftrightarrow x > 1$."}]'::jsonb, '[{"de":"$\\sqrt{2x + 4}$ xác định khi?","dapAn":"$x \\ge -2$","giaiThich":"$2x + 4 \\ge 0$.","dapAnGoc":"x ≥ −2"},{"de":"$\\sqrt{5 - x}$ xác định khi?","dapAn":"$x \\le 5$","giaiThich":"$5 - x \\ge 0$.","dapAnGoc":"x ≤ 5"}]'::jsonb),
  ('VBH-CBH-04', '$\sqrt{A^{2}}$ "gỡ" bình phương, nhưng kết quả phải không âm — nên cần giá trị tuyệt đối.', '$\sqrt{A^{2}} = |A|$, nghĩa là bằng $A$ khi $A \ge 0$ và bằng $-A$ khi $A < 0$. Trước khi bỏ dấu giá trị tuyệt đối, xét dấu của $A$.', '[{"de":"Tính $\\sqrt{(-5)^{2}}$.","giai":"Cách nghĩ sai: $-5$. Cách đúng: $\\sqrt{(-5)^{2}} = \\sqrt{25} = 5 = |-5|$."},{"de":"Rút gọn $\\sqrt{(2 - \\sqrt{5})^{2}}$.","giai":"$2 < \\sqrt{5}$ nên $2 - \\sqrt{5} < 0$; kết quả $|2 - \\sqrt{5}| = \\sqrt{5} - 2$."}]'::jsonb, '[{"de":"Với $a < 0$, $\\sqrt{a^{2}} =$ ?","dapAn":"$-a$","giaiThich":"$|a| = -a$.","dapAnGoc":"−a"},{"de":"Với $x < 3$, $\\sqrt{(x - 3)^{2}} =$ ?","dapAn":"$3 - x$","giaiThich":"$x - 3 < 0$.","dapAnGoc":"3 − x"}]'::jsonb),
  ('VBH-CBH-05', 'So sánh hai căn bậc hai hay một số với một căn: đưa về cùng dạng là xong.', 'Với $a$, $b \ge 0$: $a < b \Leftrightarrow \sqrt{a} < \sqrt{b}$. Muốn so sánh số dương với căn, viết số đó thành căn $(4 = \sqrt{16})$. Với số âm, chiều bất đẳng thức đổi ngược.', '[{"de":"So sánh $4$ và $\\sqrt{15}$.","giai":"Cách nghĩ sai: không so sánh được. Cách đúng: $4 = \\sqrt{16}$ và $16 > 15$ nên $4 > \\sqrt{15}$."},{"de":"So sánh $-\\sqrt{5}$ và $-\\sqrt{3}$.","giai":"$\\sqrt{5} > \\sqrt{3}$ nên $-\\sqrt{5} < -\\sqrt{3}$."}]'::jsonb, '[{"de":"So sánh $3$ và $\\sqrt{10}$.","dapAn":"$3 < \\sqrt{10}$","giaiThich":"$3 = \\sqrt{9} < \\sqrt{10}$.","dapAnGoc":"3 < √10"},{"de":"So sánh $\\sqrt{7}$ và $\\sqrt{6}$.","dapAn":"$\\sqrt{7} > \\sqrt{6}$","giaiThich":"$7 > 6$.","dapAnGoc":"√7 > √6"}]'::jsonb),
  ('VBH-KC-01', 'Quy tắc khai căn rất tiện cho tích, thương — nhưng không có quy tắc nào cho tổng, hiệu.', '$\sqrt{A\cdot B} = \sqrt{A} \cdot \sqrt{B}$ và $\sqrt{\dfrac{A}{B}} = \sqrt{A} / \sqrt{B}$ (với điều kiện). Với tổng, hiệu: $\sqrt{a + b} \ne \sqrt{a} + \sqrt{b}$. Phải tính tổng dưới căn trước; các căn không đồng dạng không cộng gộp được.', '[{"de":"Tính $\\sqrt{9 + 16}$.","giai":"Cách nghĩ sai: $\\sqrt{9} + \\sqrt{16} = 7$. Cách đúng: $\\sqrt{9 + 16} = \\sqrt{25} = 5$."},{"de":"Tính $\\sqrt{2} \\cdot \\sqrt{8}$.","giai":"$\\sqrt{2 \\cdot 8} = \\sqrt{16} = 4$."}]'::jsonb, '[{"de":"$\\sqrt{25 - 9} =$ ?","dapAn":"$4$","giaiThich":"$\\sqrt{16}$.","dapAnGoc":"4"},{"de":"$\\sqrt{16 \\cdot 25} =$ ?","dapAn":"$20$","giaiThich":"$4 \\cdot 5$.","dapAnGoc":"20"}]'::jsonb),
  ('VBH-KC-02', 'Tách $\sqrt{AB}$ thành $\sqrt{A} \cdot \sqrt{B}$ tiện, nhưng chỉ khi $A$ và $B$ không âm.', 'Chỉ dùng $\sqrt{A\cdot B} = \sqrt{A} \cdot \sqrt{B}$ khi $A \ge 0$ và $B \ge 0$. Nếu các thừa số âm, tính tích trước (tích hai số âm là số dương) rồi mới khai căn.', '[{"de":"Tính $\\sqrt{(-4)(-9)}$.","giai":"Cách nghĩ sai: $\\sqrt{-4} \\cdot \\sqrt{-9}$, không tính được. Cách đúng: $(-4)(-9) = 36$ nên $\\sqrt{36} = 6$."},{"de":"Tính $\\sqrt{3a} \\cdot \\sqrt{12a}$ với $a \\ge 0$.","giai":"$\\sqrt{36a^{2}} = 6a$ (vì $a \\ge 0$)."}]'::jsonb, '[{"de":"$\\sqrt{(-2)(-8)} =$ ?","dapAn":"$4$","giaiThich":"$\\sqrt{16}$.","dapAnGoc":"4"},{"de":"$\\sqrt{-4}$ có xác định không?","dapAn":"Không","giaiThich":"Số âm.","dapAnGoc":"Không"}]'::jsonb),
  ('VBH-KC-03', 'Khai căn một thương: phải khai căn cả tử và mẫu.', '$\sqrt{\dfrac{A}{B}} = \sqrt{A} / \sqrt{B}$ với $A \ge 0$, $B > 0$. Ngược lại, $\sqrt{A} / \sqrt{B} = \sqrt{\dfrac{A}{B}}$.', '[{"de":"Tính $\\sqrt{\\dfrac{9}{4}}$.","giai":"Cách nghĩ sai: $\\sqrt{9} / 4 = \\dfrac{3}{4}$. Cách đúng: $\\sqrt{9} / \\sqrt{4} = \\dfrac{3}{2}$."},{"de":"Tính $\\sqrt{50} : \\sqrt{2}$.","giai":"$\\sqrt{50 : 2} = \\sqrt{25} = 5$."}]'::jsonb, '[{"de":"$\\sqrt{\\dfrac{49}{81}} =$ ?","dapAn":"$\\dfrac{7}{9}$","giaiThich":"Khai căn tử và mẫu.","dapAnGoc":"7/9"},{"de":"$\\sqrt{72} : \\sqrt{2} =$ ?","dapAn":"$6$","giaiThich":"$\\sqrt{36}$.","dapAnGoc":"6"}]'::jsonb),
  ('VBH-BD-01', 'Đưa thừa số ra ngoài dấu căn giúp biểu thức gọn hơn — miễn là đưa ra đúng phần chính phương.', '$\sqrt{A^{2}B} = |A|\sqrt{B} (B \ge 0)$. Tách số dưới căn thành tích (số chính phương lớn nhất) $\times$ (phần còn lại), rồi đưa căn của số chính phương ra ngoài. Nếu thừa số có thể âm thì lấy giá trị tuyệt đối.', '[{"de":"Đưa thừa số ra ngoài: $\\sqrt{18}$.","giai":"Cách nghĩ sai: $9\\sqrt{2}$ (quên khai căn $9$). Cách đúng: $\\sqrt{9 \\cdot 2} = 3\\sqrt{2}$."},{"de":"Với $x < 0$, $y \\ge 0$: $\\sqrt{9x^{2}y}$.","giai":"$\\sqrt{9x^{2}y} = 3|x|\\sqrt{y} = -3x\\sqrt{y}$."}]'::jsonb, '[{"de":"$\\sqrt{12} =$ ?","dapAn":"$2\\sqrt{3}$","giaiThich":"$\\sqrt{4 \\cdot 3}$.","dapAnGoc":"2√3"},{"de":"$\\sqrt{50} =$ ?","dapAn":"$5\\sqrt{2}$","giaiThich":"$\\sqrt{25 \\cdot 2}$.","dapAnGoc":"5√2"}]'::jsonb),
  ('VBH-BD-02', 'Đưa thừa số vào trong dấu căn là phép ngược: thừa số phải bình phương lên, còn dấu "$-$" ở lại ngoài.', '$A\sqrt{B} = \sqrt{A^{2}B}$ khi $A \ge 0$; $A\sqrt{B} = -\sqrt{A^{2}B}$ khi $A < 0$. Dùng để so sánh các căn: đưa hết vào trong rồi so sánh số dưới căn.', '[{"de":"Viết $-2\\sqrt{3}$ dưới dạng một căn (có dấu nếu cần).","giai":"Cách nghĩ sai: $\\sqrt{12}$ (một số dương). Cách đúng: $-2\\sqrt{3}$ âm nên $-2\\sqrt{3} = -\\sqrt{4 \\cdot 3} = -\\sqrt{12}$."},{"de":"So sánh $3\\sqrt{5}$ và $5\\sqrt{3}$.","giai":"$3\\sqrt{5} = \\sqrt{45}$, $5\\sqrt{3} = \\sqrt{75}$; $45 < 75$ nên $3\\sqrt{5} < 5\\sqrt{3}$."}]'::jsonb, '[{"de":"$2\\sqrt{3} =$ ?","dapAn":"$\\sqrt{12}$","giaiThich":"$2^{2} \\cdot 3 = 12$.","dapAnGoc":"√12"},{"de":"Với $a \\ge 0$, $a\\sqrt{7} =$ ?","dapAn":"$\\sqrt{7a^{2}}$","giaiThich":"Bình phương $a$.","dapAnGoc":"√(7a²)"}]'::jsonb),
  ('VBH-BD-03', 'Trục căn thức ở mẫu: chọn đúng "người bạn" để nhân thì mẫu sẽ hết căn.', 'Mẫu $\sqrt{b}$: nhân cả tử và mẫu với $\sqrt{b}$. Mẫu $\sqrt{b} \pm c$: nhân cả tử và mẫu với biểu thức liên hợp $\sqrt{b} \mp c$ (đổi dấu ở giữa), dùng $(x + y)(x - y) = x^{2} - y^{2}$.', '[{"de":"Trục căn: $1/(\\sqrt{5} - 2)$.","giai":"Cách nghĩ sai: nhân với $\\sqrt{5} - 2$, mẫu thành $(\\sqrt{5} - 2)^{2}$, vẫn còn căn. Cách đúng: nhân với $\\sqrt{5} + 2$: $(\\sqrt{5} + 2)/(5 - 4) = \\sqrt{5} + 2$."},{"de":"Trục căn: $2/(\\sqrt{3} + 1)$.","giai":"$2(\\sqrt{3} - 1)/(3 - 1) = \\sqrt{3} - 1$."}]'::jsonb, '[{"de":"$1/\\sqrt{2} =$ ?","dapAn":"$\\sqrt{2}/2$","giaiThich":"Nhân $\\sqrt{2}$.","dapAnGoc":"√2/2"},{"de":"Liên hợp của $\\sqrt{5} + 2$?","dapAn":"$\\sqrt{5} - 2$","giaiThich":"Đổi dấu ở giữa.","dapAnGoc":"√5 − 2"}]'::jsonb),
  ('VBH-BD-04', 'Hằng đẳng thức hiệu hai bình phương là "chìa khóa" của mọi phép trục căn hai căn thức.', '$(\sqrt{a} + \sqrt{b})(\sqrt{a} - \sqrt{b}) = (\sqrt{a})^{2} - (\sqrt{b})^{2} = a - b$ (không phải $a + b$, không phải $a^{2} - b^{2}$). Bình phương một tổng: $(\sqrt{a} + b)^{2} = a + 2b\sqrt{a} + b^{2}$.', '[{"de":"Tính $(\\sqrt{6} + \\sqrt{2})(\\sqrt{6} - \\sqrt{2})$.","giai":"Cách nghĩ sai: $6^{2} - 2^{2} = 32$. Cách đúng: $(\\sqrt{6})^{2} - (\\sqrt{2})^{2} = 6 - 2 = 4$."},{"de":"Tính $(\\sqrt{3} + 1)^{2}$.","giai":"$3 + 2\\sqrt{3} + 1 = 4 + 2\\sqrt{3}$."}]'::jsonb, '[{"de":"$(\\sqrt{7} - \\sqrt{5})(\\sqrt{7} + \\sqrt{5}) =$ ?","dapAn":"$2$","giaiThich":"$7 - 5$.","dapAnGoc":"2"},{"de":"$(\\sqrt{2} + 1)^{2} =$ ?","dapAn":"$3 + 2\\sqrt{2}$","giaiThich":"$2 + 2\\sqrt{2} + 1$.","dapAnGoc":"3 + 2√2"}]'::jsonb),
  ('VBH-BD-05', 'Rút gọn biểu thức chứa căn giống thu gọn đa thức: chỉ gộp các hạng tử "cùng loại".', 'Đưa mỗi căn về dạng $a\sqrt{b}$ với $b$ nhỏ nhất; chỉ cộng, trừ các căn có cùng $\sqrt{b}$. Phối hợp trục căn, hằng đẳng thức; luôn ghi điều kiện xác định.', '[{"de":"Rút gọn $\\sqrt{20} - \\sqrt{45} + \\sqrt{5}$.","giai":"Cách nghĩ sai: gộp thành $\\sqrt{20 - 45 + 5}$. Cách đúng: $2\\sqrt{5} - 3\\sqrt{5} + \\sqrt{5} = 0$."},{"de":"Rút gọn $(\\sqrt{12} + \\sqrt{27} - \\sqrt{3}) : \\sqrt{3}$.","giai":"$(2\\sqrt{3} + 3\\sqrt{3} - \\sqrt{3}) : \\sqrt{3} = 4\\sqrt{3} : \\sqrt{3} = 4$."}]'::jsonb, '[{"de":"$3\\sqrt{2} + 5\\sqrt{2} =$ ?","dapAn":"$8\\sqrt{2}$","giaiThich":"Cùng $\\sqrt{2}$.","dapAnGoc":"8√2"},{"de":"$\\sqrt{2} + \\sqrt{8} =$ ?","dapAn":"$3\\sqrt{2}$","giaiThich":"$\\sqrt{8} = 2\\sqrt{2}$.","dapAnGoc":"3√2"}]'::jsonb),
  ('VBH-CBB-01', 'Căn bậc ba "dễ tính" hơn căn bậc hai: số nào cũng có, và chỉ có một.', 'Căn bậc ba của $a$ là số $x$ mà $x^{3} = a$. Mọi số thực có đúng một căn bậc ba. Căn bậc ba của số âm là số âm. $a < b \Leftrightarrow \sqrt[3]{a} < \sqrt[3]{b}$.', '[{"de":"Tính $\\sqrt[3]{-8}$.","giai":"Cách nghĩ sai: không xác định (giống căn bậc hai). Cách đúng: $(-2)^{3} = -8$ nên $\\sqrt[3]{-8} = -2$."},{"de":"So sánh $3$ và $\\sqrt[3]{26}$.","giai":"$3 = \\sqrt[3]{27} > \\sqrt[3]{26}$."}]'::jsonb, '[{"de":"$\\sqrt[3]{27} =$ ?","dapAn":"$3$","giaiThich":"$3^{3} = 27$.","dapAnGoc":"3"},{"de":"$\\sqrt[3]{-64} =$ ?","dapAn":"$-4$","giaiThich":"$(-4)^{3} = -64$.","dapAnGoc":"−4"}]'::jsonb),
  ('VBH-CBB-02', 'Đừng mang "điều kiện $A \ge 0$" và "giá trị tuyệt đối" của căn bậc hai sang căn bậc ba.', 'Căn thức bậc ba $\sqrt[3]{A}$ xác định khi $A$ xác định (không cần $A \ge 0$). $\sqrt[3]{A^{3}} = A$ với mọi $A$.', '[{"de":"$\\sqrt[3]{x - 2}$ xác định khi nào?","giai":"Cách nghĩ sai: $x \\ge 2$. Cách đúng: $x - 2$ luôn xác định nên $\\sqrt[3]{x - 2}$ xác định với mọi $x$."},{"de":"Tính $\\sqrt[3]{(-3)^{3}}$.","giai":"$\\sqrt[3]{(-3)^{3}} = -3$ (không phải $3$)."}]'::jsonb, '[{"de":"$\\sqrt[3]{8x^{3}} =$ ?","dapAn":"$2x$","giaiThich":"Không lấy trị tuyệt đối.","dapAnGoc":"2x"},{"de":"$\\sqrt[3]{1/(x - 1)}$ xác định khi?","dapAn":"$x \\ne 1$","giaiThich":"Chỉ cần mẫu khác $0$.","dapAnGoc":"x ≠ 1"}]'::jsonb)
on conflict (content_id) do update set dan = excluded.dan, quy_tac = excluded.quy_tac,
  vi_du = excluded.vi_du, tu_lam = excluded.tu_lam, updated_at = now();

