  nguon = case when contents.url is null or contents.url = '' then excluded.nguon else contents.nguon end,
  url = case when contents.url is null or contents.url = '' then excluded.url else contents.url end;

insert into error_dictionary (error_code, ku_id, misconception, remediation_id) values
  ('E-TSLG-01', 'C4-B11-M1', 'Xác định cạnh đối, cạnh kề sai (lấy theo góc vuông hoặc theo góc kia) nên viết sin, cos, tan sai. Ví dụ: Tam giác ABC vuông tại A: sin B = AB/BC', 'VBH-TSLG-01'),
  ('E-TSLG-02', 'C4-B11-M1', 'Nhớ đảo định nghĩa (sin = kề/huyền, tan = kề/đối), lấy huyền ở tử, hoặc cho rằng sin, cos có thể lớn hơn 1. Ví dụ: sin α = huyền/đối; tan B = AB/AC', 'VBH-TSLG-02'),
  ('E-TSLG-03', 'C4-B11-M2', 'Nhớ nhầm giá trị sin, cos, tan của 30°, 45°, 60° (đổi chỗ 1/2 và √3/2, √3 và √3/3). Ví dụ: sin 30° = √3/2; tan 60° = √3/3', 'VBH-TSLG-03'),
  ('E-TSLG-04', 'C4-B11-M3', 'Nhầm góc phụ với góc bù, hoặc cho rằng sin α = sin(90° − α). Ví dụ: sin 50° = sin 40°; hai góc phụ nhau có tổng 180°', 'VBH-TSLG-04'),
  ('E-HTL-01', 'C4-B12-M1', 'Tính cạnh góc vuông bằng cạnh huyền nhân sai tỉ số (sin thay cos), hoặc chia thay vì nhân. Ví dụ: BC = 12, góc B = 60°: AB = 12·sin 60°', 'VBH-HTL-01'),
  ('E-HTL-02', 'C4-B12-M2', 'Tính cạnh góc vuông từ cạnh góc vuông kia mà dùng tan của góc kề (hoặc chia cho tan) sai. Ví dụ: AB = 3, góc B = 60°: AC = 3·tan 30°', 'VBH-HTL-02'),
  ('E-HTL-03', 'C4-B12-M3', 'Bấm máy ở chế độ radian, làm tròn sai, hoặc xác định sai góc nâng, góc hạ trong bài toán thực tế. Ví dụ: Góc hạ 25° từ toà nhà cao 30 m: khoảng cách = 30·tan 25°', 'VBH-HTL-03'),
  ('E-HTL-04', 'C4-B12-M3', 'Tính góc còn lại theo tổng 180° bỏ qua góc vuông, hoặc giải tam giác vuông còn thiếu yếu tố. Ví dụ: Góc B = 35° thì góc C = 145°', 'VBH-HTL-04')
on conflict (error_code) do update set ku_id = excluded.ku_id, misconception = excluded.misconception,
  remediation_id = excluded.remediation_id;

insert into questions (question_id, ku_id, level, stem, correct_option, expected_time_sec, hinh, trang_thai, ghi_chu_gv, nguoi_duyet, ngay_duyet) values
  ('C4-B11-M1-Q01', 'C4-B11-M1', 1, 'Tam giác $ABC$ vuông tại $A$. Cạnh đối của góc $B$ là:', 'A', 45, null, 'nhap', null, null, null),
  ('C4-B11-M1-Q02', 'C4-B11-M1', 1, 'Tam giác $ABC$ vuông tại $A$. $\sin B$ bằng:', 'A', 45, null, 'nhap', null, null, null),
  ('C4-B11-M1-Q03', 'C4-B11-M1', 2, 'Tam giác $ABC$ vuông tại $A$ có $AB = 3$, $AC = 4$, $BC = 5$. $\tan B$ bằng:', 'A', 60, '{"loai":"tam-giac-vuong","dinh":["A","B","C"],"canh":{"tren":"3","ngang":"4","huyen":"5"},"moTa":"Tam giác ABC vuông tại A; BA = 3, AC = 4, BC = 5."}'::jsonb, 'nhap', null, null, null),
  ('C4-B11-M1-Q04', 'C4-B11-M1', 2, 'Tam giác $ABC$ vuông tại $A$ có $AB = 3$, $AC = 4$, $BC = 5$. $\cos C$ bằng:', 'A', 60, '{"loai":"tam-giac-vuong","dinh":["A","B","C"],"canh":{"tren":"3","ngang":"4","huyen":"5"},"moTa":"Tam giác ABC vuông tại A; BA = 3, AC = 4, BC = 5."}'::jsonb, 'nhap', null, null, null),
  ('C4-B11-M1-Q05', 'C4-B11-M1', 3, 'Cho góc nhọn $\alpha$ có $\sin \alpha = \dfrac{3}{5}$. Khi đó $\cos \alpha$ bằng:', 'A', 90, null, 'nhap', null, null, null),
  ('C4-B11-M1-Q06', 'C4-B11-M1', 3, 'Tam giác $MNP$ vuông tại $M$ có $MN = 6$, $NP = 10$. $\sin P$ bằng:', 'A', 90, '{"loai":"tam-giac-vuong","dinh":["M","N","P"],"canh":{"tren":"6","huyen":"10"},"moTa":"Tam giác MNP vuông tại M; NM = 6, NP = 10."}'::jsonb, 'nhap', null, null, null),
  ('C4-B11-M1-Q07', 'C4-B11-M1', 2, 'Với mọi góc nhọn $\alpha$, khẳng định nào đúng?', 'A', 60, null, 'nhap', null, null, null),
  ('C4-B11-M1-Q08', 'C4-B11-M1', 4, 'Một chiếc thang dài $4$ m dựa vào tường, chân thang cách chân tường $1{,}5$ m. Gọi $\alpha$ là góc giữa thang và mặt đất. $\cos \alpha$ bằng:', 'A', 120, '{"loai":"tam-giac-vuong","dinh":["","",""],"canh":{"ngang":"1,5 m","huyen":"4 m"},"goc":{"phai":"α"},"nhanCanh":{"tren":"tường","ngang":"mặt đất","huyen":"thang"},"moTa":"Thang dài 4 m dựa vào tường, chân thang cách chân tường 1,5 m, α là góc giữa thang và mặt đất."}'::jsonb, 'nhap', null, null, null),
  ('C4-B11-M1-Q09', 'C4-B11-M1', 1, 'Tam giác $ABC$ vuông tại $A$. Cạnh kề của góc $C$ là:', 'A', 45, null, 'nhap', null, null, null),
  ('C4-B11-M1-Q10', 'C4-B11-M1', 1, 'Tam giác $ABC$ vuông tại $A$. $\cos B$ bằng:', 'A', 45, null, 'nhap', null, null, null),
  ('C4-B11-M1-Q11', 'C4-B11-M1', 2, 'Tam giác $ABC$ vuông tại $A$ có $AB = 6$, $AC = 8$, $BC = 10$. $\sin C$ bằng:', 'A', 60, '{"loai":"tam-giac-vuong","dinh":["A","B","C"],"canh":{"tren":"6","ngang":"8","huyen":"10"},"moTa":"Tam giác ABC vuông tại A; BA = 6, AC = 8, BC = 10."}'::jsonb, 'nhap', null, null, null),
  ('C4-B11-M1-Q12', 'C4-B11-M1', 2, 'Tam giác $ABC$ vuông tại $A$ có $AB = 6$, $AC = 8$, $BC = 10$. $\cot B$ bằng:', 'A', 60, '{"loai":"tam-giac-vuong","dinh":["A","B","C"],"canh":{"tren":"6","ngang":"8","huyen":"10"},"moTa":"Tam giác ABC vuông tại A; BA = 6, AC = 8, BC = 10."}'::jsonb, 'nhap', null, null, null),
