  ('C4-B12-M2-Q14', 'C4-B12-M2', 3, 'Một cột đèn cao $7$ m có bóng trên mặt đất dài $4$ m. Góc tạo bởi tia nắng và mặt đất khoảng (làm tròn đến độ):', 'A', 90, '{"loai":"tam-giac-vuong","dinh":["","",""],"canh":{"tren":"7 m","ngang":"4 m"},"goc":{"phai":"?"},"nhanCanh":{"tren":"cột đèn","ngang":"bóng","huyen":"tia nắng"},"moTa":"Cột đèn cao 7 m, bóng trên mặt đất dài 4 m; cần tìm góc giữa tia nắng và mặt đất."}'::jsonb, 'nhap', null, null, null),
  ('C4-B12-M2-Q15', 'C4-B12-M2', 4, 'Hai bạn đứng cách nhau $20$ m, thẳng hàng và cùng phía với chân một tháp. Bạn đứng gần nhìn đỉnh tháp với góc nâng $45^{\circ}$, bạn đứng xa nhìn với góc nâng $30^{\circ}$. Bỏ qua chiều cao của người, chiều cao tháp khoảng (làm tròn đến hàng phần mười):', 'A', 120, null, 'nhap', null, null, null),
  ('C4-B12-M2-Q16', 'C4-B12-M2', 4, 'Từ vị trí $A$ cao $35$ m trên một toà nhà, người ta nhìn thấy ô tô ở vị trí $C$ dưới góc hạ $60^{\circ}$ (góc giữa tia $AC$ và phương nằm ngang). Khoảng cách từ ô tô đến chân toà nhà $B$ (làm tròn đến hàng phần mười) là (Đề thi vào $10$ Đà Nẵng $2026$, câu $4a$):', 'A', 120, null, 'nhap', null, null, null),
  ('C4-B12-M3-Q01', 'C4-B12-M3', 1, 'Giải tam giác vuông là:', 'A', 45, null, 'nhap', null, null, null),
