  ('C4-B12-M3-Q03', 'C4-B12-M3', 2, 'Tam giác $ABC$ vuông tại $A$ có $AB = 6$ cm, $BC = 10$ cm. Khẳng định đúng là:', 'A', 60, '{"loai":"tam-giac-vuong","dinh":["A","B","C"],"canh":{"tren":"6 cm","ngang":"?","huyen":"10 cm"},"goc":{"tren":"?"},"moTa":"Tam giác ABC vuông tại A; BA = 6 cm, AC cần tìm, BC = 10 cm, góc B cần tìm."}'::jsonb, 'nhap', null, null, null),
  ('C4-B12-M3-Q04', 'C4-B12-M3', 2, 'Để tìm góc nhọn $\alpha$ biết $\sin \alpha = 0{,}5$ bằng máy tính cầm tay, ta làm:', 'A', 60, null, 'nhap', null, null, null),
  ('C4-B12-M3-Q05', 'C4-B12-M3', 3, 'Tam giác $ABC$ vuông tại $A$ có $BC = 15$ cm, góc $B = 40^{\circ}$. Độ dài $AC$ (làm tròn đến hàng phần mười) là:', 'A', 90, '{"loai":"tam-giac-vuong","dinh":["A","B","C"],"canh":{"ngang":"?","huyen":"15 cm"},"goc":{"tren":"40°"},"moTa":"Tam giác ABC vuông tại A; AC cần tìm, BC = 15 cm, góc B = 40°."}'::jsonb, 'nhap', null, null, null),
