  ('C4-B12-M3-Q07', 'C4-B12-M3', 4, 'Một máy bay cất cánh theo đường thẳng tạo với mặt đất góc $20^{\circ}$. Sau khi bay được $5$ km theo đường đó, máy bay ở độ cao khoảng (làm tròn đến hàng phần trăm):', 'A', 120, '{"loai":"tam-giac-vuong","dinh":["","",""],"canh":{"tren":"?","huyen":"5 km"},"goc":{"phai":"20°"},"nhanCanh":{"tren":"độ cao","ngang":"mặt đất","huyen":"đường bay"},"moTa":"Máy bay bay theo đường thẳng tạo với mặt đất góc 20°, đã bay được 5 km; cần tìm độ cao."}'::jsonb, 'nhap', null, null, null),
  ('C4-B12-M3-Q08', 'C4-B12-M3', 4, 'Một con dốc dài $120$ m, đỉnh dốc cao hơn chân dốc $15$ m. Góc giữa mặt dốc và phương nằm ngang khoảng (làm tròn đến độ):', 'A', 120, '{"loai":"tam-giac-vuong","dinh":["","",""],"canh":{"tren":"15 m","huyen":"120 m"},"goc":{"phai":"?"},"nhanCanh":{"tren":"độ cao","huyen":"mặt dốc"},"moTa":"Mặt dốc dài 120 m, đỉnh dốc cao hơn chân dốc 15 m; cần tìm góc giữa mặt dốc và phương nằm ngang."}'::jsonb, 'nhap', null, null, null),
  ('C4-B12-M3-Q09', 'C4-B12-M3', 1, 'Tam giác $ABC$ vuông tại $A$ có góc $C = 62^{\circ}$. Số đo góc $B$ là:', 'A', 45, null, 'nhap', null, null, null),
  ('C4-B12-M3-Q10', 'C4-B12-M3', 1, 'Để giải được một tam giác vuông, ngoài góc vuông ta cần biết ít nhất:', 'A', 45, null, 'nhap', null, null, null),
  ('C4-B12-M3-Q11', 'C4-B12-M3', 2, 'Tam giác $ABC$ vuông tại $A$ có $AB = 5$ cm, $AC = 12$ cm. Độ dài $BC$ và số đo góc $B$ (làm tròn đến độ) là:', 'A', 60, '{"loai":"tam-giac-vuong","dinh":["A","B","C"],"canh":{"tren":"5 cm","ngang":"12 cm","huyen":"?"},"goc":{"tren":"?"},"moTa":"Tam giác ABC vuông tại A; BA = 5 cm, AC = 12 cm, BC cần tìm, góc B cần tìm."}'::jsonb, 'nhap', null, null, null),
  ('C4-B12-M3-Q12', 'C4-B12-M3', 2, 'Máy tính cầm tay đang ở chế độ độ $(D)$. Để tìm góc nhọn $\alpha$ biết $\tan \alpha = 1{,}2$, ta bấm:', 'A', 60, null, 'nhap', null, null, null),
