  ('C4-B12-M3-Q15', 'C4-B12-M3', 3, 'Một đoạn đường dốc dài $200$ m, góc giữa mặt đường và phương nằm ngang là $9^{\circ}$. Đi hết đoạn dốc thì lên cao thêm khoảng (làm tròn đến hàng phần mười):', 'A', 90, '{"loai":"tam-giac-vuong","dinh":["","",""],"canh":{"tren":"?","huyen":"200 m"},"goc":{"phai":"9°"},"nhanCanh":{"tren":"độ cao","huyen":"mặt đường dốc"},"moTa":"Đoạn đường dốc dài 200 m, góc giữa mặt đường và phương nằm ngang là 9°; cần tìm độ cao lên thêm."}'::jsonb, 'nhap', null, null, null),
