  ('HL-C5-B16-M3', 'C5-B16-M3', 'hoc-lieu', 2, 'Phiếu hướng dẫn tự học: Tính chất hai tiếp tuyến cắt nhau', null, '/phieu/C5-B16-M3', null),
  ('VD-C5-B17-M1', 'C5-B17-M1', 'video', 2, 'Video bài học: Ba vị trí tương đối của hai đường tròn', 704, 'https://www.youtube.com/watch?v=cXURMs7uUgg', 'OLM.VN — kênh YouTube @olm_vn, danh sách phát Toán lớp 9 mới (dùng lại, ghi nguồn)'),
  ('HL-C5-B17-M1', 'C5-B17-M1', 'hoc-lieu', 2, 'Phiếu hướng dẫn tự học: Ba vị trí tương đối của hai đường tròn', null, '/phieu/C5-B17-M1', null),
  ('VD-C5-B17-M2', 'C5-B17-M2', 'video', 2, 'Video bài học: Vị trí tương đối và khoảng cách giữa hai tâm', 683, 'https://www.youtube.com/watch?v=qkjt7Dgwj9U', 'OLM.VN — kênh YouTube @olm_vn, danh sách phát Toán lớp 9 mới (dùng lại, ghi nguồn)'),
  ('HL-C5-B17-M2', 'C5-B17-M2', 'hoc-lieu', 2, 'Phiếu hướng dẫn tự học: Vị trí tương đối và khoảng cách giữa hai tâm', null, '/phieu/C5-B17-M2', null),
  ('VBH-DTR-01', 'C5-B13-M1', 'micro-lesson', 1, 'Vi bài học: So sánh khoảng cách đến tâm với R; R = đường kính : 2', 300, null, null),
  ('VBH-DTR-02', 'C5-B13-M2', 'micro-lesson', 1, 'Vi bài học: Tâm là tâm đối xứng; mọi đường thẳng qua tâm là trục đối xứng', 240, null, null),
  ('VBH-CD-01', 'C5-B14-M1', 'micro-lesson', 1, 'Vi bài học: Dây ≤ đường kính; d² + (dây/2)² = R²', 360, null, null),
  ('VBH-CD-02', 'C5-B14-M2', 'micro-lesson', 1, 'Vi bài học: sđ cung nhỏ = góc ở tâm; sđ cung lớn = 360° − sđ cung nhỏ', 300, null, null),
  ('VBH-CD-03', 'C5-B14-M3', 'micro-lesson', 1, 'Vi bài học: Cộng cung khi điểm nằm trên cung; so sánh cung trong cùng đường tròn', 300, null, null),
  ('VBH-QH-01', 'C5-B15-M1', 'micro-lesson', 1, 'Vi bài học: l = πRn/180; C = 2πR', 300, null, null),
  ('VBH-QH-02', 'C5-B15-M2', 'micro-lesson', 1, 'Vi bài học: S = πR²n/360 = lR/2', 300, null, null),
  ('VBH-QH-03', 'C5-B15-M3', 'micro-lesson', 1, 'Vi bài học: S = π(R² − r²), không phải π(R − r)²', 300, null, null),
  ('VBH-TT-01', 'C5-B16-M1', 'micro-lesson', 1, 'Vi bài học: d < R: cắt; d = R: tiếp xúc; d > R: không giao', 300, null, null),
  ('VBH-TT-02', 'C5-B16-M2', 'micro-lesson', 1, 'Vi bài học: Tiếp tuyến ⊥ bán kính tại tiếp điểm; MA² = OM² − R²', 360, null, null),
  ('VBH-TT-03', 'C5-B16-M3', 'micro-lesson', 1, 'Vi bài học: MA = MB; MO là phân giác; OM ⊥ AB', 360, null, null),
  ('VBH-HDT-01', 'C5-B17-M1', 'micro-lesson', 1, 'Vi bài học: 2 điểm chung: cắt; 1: tiếp xúc; 0: không giao', 300, null, null),
  ('VBH-HDT-02', 'C5-B17-M2', 'micro-lesson', 1, 'Vi bài học: Tiếp xúc ngoài: d = R + r; tiếp xúc trong: d = R − r', 360, null, null)
-- Link video: chỉ điền khi ô còn trống — link giáo viên đã tự gắn ở /gv/noi-dung được giữ nguyên.
on conflict (content_id) do update set title = excluded.title, ku_id = excluded.ku_id,
  duration_sec = case when contents.url is null or contents.url = '' then excluded.duration_sec else contents.duration_sec end,
  nguon = case when contents.url is null or contents.url = '' then excluded.nguon else contents.nguon end,
  url = case when contents.url is null or contents.url = '' then excluded.url else contents.url end;

insert into error_dictionary (error_code, ku_id, misconception, remediation_id) values
  ('E-DTR-01', 'C5-B13-M1', 'So sánh khoảng cách từ điểm đến tâm với bán kính sai chiều, hoặc nhầm bán kính với đường kính. Ví dụ: OM = 2 < R = 3 nhưng kết luận M nằm ngoài; đường kính 10 thì R = 10', 'VBH-DTR-01'),
  ('E-DTR-02', 'C5-B13-M2', 'Cho rằng đường tròn chỉ có một hoặc hai trục đối xứng, hoặc trục đối xứng là dây bất kì. Ví dụ: Đường tròn có 2 trục đối xứng', 'VBH-DTR-02'),
  ('E-CD-01', 'C5-B14-M1', 'Cho dây dài hơn đường kính, hoặc áp dụng Pythagore với cả dây thay vì nửa dây. Ví dụ: R = 5, dây 8: d = √(5² − 8²)', 'VBH-CD-01'),
  ('E-CD-02', 'C5-B14-M2', 'Lấy số đo cung bằng nửa góc ở tâm, nhầm cung lớn với cung nhỏ, hoặc nhầm góc ở tâm với góc có đỉnh trên đường tròn. Ví dụ: Góc AOB = 70° thì cung lớn AB = 70°', 'VBH-CD-02'),
  ('E-CD-03', 'C5-B14-M3', 'Cộng hai cung không kề nhau, so sánh cung ở hai đường tròn khác nhau, hoặc tính tổng các cung khác 360°. Ví dụ: Hai cung 60° ở hai đường tròn khác nhau là bằng nhau', 'VBH-CD-03'),
  ('E-QH-01', 'C5-B15-M1', 'Tính độ dài cung bằng πRn/360, dùng đường kính thay bán kính, hoặc nhầm với công thức diện tích. Ví dụ: Cung 60°, R = 6: l = π·6·60/360 = π', 'VBH-QH-01'),
  ('E-QH-02', 'C5-B15-M2', 'Tính diện tích hình quạt bằng πR²n/180, lấy l·R không chia 2, hoặc dùng πR thay πR². Ví dụ: R = 6, n = 60°: S = 36π·60/180 = 12π', 'VBH-QH-02'),
  ('E-QH-03', 'C5-B15-M3', 'Tính diện tích hình vành khuyên bằng π(R − r)², hoặc dùng đường kính thay bán kính. Ví dụ: R = 5, r = 3: S = π(5 − 3)² = 4π', 'VBH-QH-03'),
  ('E-TT-01', 'C5-B16-M1', 'Xác định vị trí tương đối của đường thẳng và đường tròn sai khi so sánh khoảng cách d với R. Ví dụ: d = R thì đường thẳng cắt đường tròn tại hai điểm', 'VBH-TT-01'),
  ('E-TT-02', 'C5-B16-M2', 'Kết luận tiếp tuyến khi thiếu điều kiện điểm thuộc đường tròn hoặc vuông góc, hoặc dùng Pythagore sai cạnh huyền (OM). Ví dụ: OM = 10, R = 6: MA = √(10² + 6²)', 'VBH-TT-02'),
  ('E-TT-03', 'C5-B16-M3', 'Nhầm các tính chất của hai tiếp tuyến cắt nhau: cho MA = OA, lấy góc AMO bằng góc AMB, quên OM là trung trực của AB. Ví dụ: Góc AMB = 60° thì góc AMO = 60°', 'VBH-TT-03'),
  ('E-HDT-01', 'C5-B17-M1', 'Liên hệ sai số điểm chung với vị trí hai đường tròn, hoặc quên tính chất đường nối tâm. Ví dụ: Hai đường tròn tiếp xúc thì O, O′, A không thẳng hàng', 'VBH-HDT-01'),
  ('E-HDT-02', 'C5-B17-M2', 'So sánh d với R + r và R − r sai, nhầm tiếp xúc ngoài với tiếp xúc trong. Ví dụ: R = 5, r = 3, d = 2 thì tiếp xúc ngoài', 'VBH-HDT-02')
on conflict (error_code) do update set ku_id = excluded.ku_id, misconception = excluded.misconception,
  remediation_id = excluded.remediation_id;

