  ('C5-B13-M1-Q01', 'C5-B13-M1', 1, 'Đường tròn tâm $O$ bán kính $5$ cm là tập hợp các điểm:', 'A', 45, null, 'nhap', null, null, null),
  ('C5-B13-M1-Q02', 'C5-B13-M1', 1, 'Cho ($O; 3$ cm) và điểm $M$ với $OM = 2$ cm. Điểm $M$ nằm:', 'A', 45, null, 'nhap', null, null, null),
  ('C5-B13-M1-Q03', 'C5-B13-M1', 2, 'Đường tròn có đường kính $10$ cm thì bán kính là:', 'A', 60, null, 'nhap', null, null, null),
  ('C5-B13-M1-Q04', 'C5-B13-M1', 2, 'Cho ($O; 4$ cm), điểm $A$ với $OA = 4$ cm, điểm $B$ với $OB = 5$ cm. Khẳng định đúng là:', 'A', 60, null, 'nhap', null, null, null),
  ('C5-B13-M1-Q05', 'C5-B13-M1', 3, 'Trong mặt phẳng toạ độ, đường tròn tâm $O(0; 0)$ bán kính $5$ đi qua điểm nào?', 'A', 90, null, 'nhap', null, null, null),
  ('C5-B13-M1-Q06', 'C5-B13-M1', 3, 'Tam giác $ABC$ vuông tại $A$ có $BC = 10$ cm. Đường tròn đi qua ba điểm $A$, $B$, $C$ có bán kính:', 'A', 90, null, 'nhap', null, null, null),
  ('C5-B13-M1-Q07', 'C5-B13-M1', 4, 'Hình chữ nhật $ABCD$ có $AB = 6$ cm, $BC = 8$ cm. Bốn điểm $A$, $B$, $C$, $D$ cùng thuộc một đường tròn có bán kính:', 'A', 120, null, 'nhap', null, null, null),
  ('C5-B13-M1-Q08', 'C5-B13-M1', 2, 'Một chiếc compa mở rộng $3$ cm vẽ đường tròn. Điểm $M$ cách tâm $2{,}9$ cm, điểm $N$ cách tâm $3{,}1$ cm. Khẳng định đúng là:', 'A', 60, null, 'nhap', null, null, null),
  ('C5-B13-M1-Q09', 'C5-B13-M1', 1, 'Cho ($O; 4$ cm) và điểm $M$ với $OM = 6$ cm. Điểm $M$ nằm:', 'A', 45, null, 'nhap', null, null, null),
  ('C5-B13-M1-Q10', 'C5-B13-M1', 1, 'Đường tròn có bán kính $7$ cm thì đường kính là:', 'A', 45, null, 'nhap', null, null, null),
  ('C5-B13-M1-Q11', 'C5-B13-M1', 2, 'Cho ($O; 5$ cm). Điểm nào nằm trên đường tròn?', 'A', 60, null, 'nhap', null, null, null),
  ('C5-B13-M1-Q12', 'C5-B13-M1', 2, 'Cho đoạn thẳng $AB = 6$ cm. Đường tròn đường kính $AB$ có tâm và bán kính là:', 'A', 60, null, 'nhap', null, null, null),
  ('C5-B13-M1-Q13', 'C5-B13-M1', 3, 'Trong mặt phẳng toạ độ, cho điểm $M(6; 8)$ và đường tròn tâm $O(0; 0)$ bán kính $10$. Điểm $M$ nằm:', 'A', 90, null, 'nhap', null, null, null),
  ('C5-B13-M1-Q14', 'C5-B13-M1', 3, 'Tam giác $ABC$ vuông tại $A$ có $AB = 5$ cm, $AC = 12$ cm. Bán kính đường tròn đi qua ba điểm $A$, $B$, $C$ là:', 'A', 90, null, 'nhap', null, null, null),
  ('C5-B13-M1-Q15', 'C5-B13-M1', 4, 'Hình vuông $ABCD$ cạnh $4$ cm. Bán kính đường tròn đi qua bốn đỉnh của hình vuông là:', 'A', 120, null, 'nhap', null, null, null),
  ('C5-B13-M1-Q16', 'C5-B13-M1', 4, 'Một loa phát thanh đặt tại $O$ nghe rõ trong bán kính $300$ m. Nhà An cách $O 0{,}25$ km, nhà Bình cách $O 350$ m. Khẳng định đúng là:', 'A', 120, null, 'nhap', null, null, null),
  ('C5-B13-M2-Q01', 'C5-B13-M2', 1, 'Tâm đối xứng của đường tròn là:', 'A', 45, null, 'nhap', null, null, null),
  ('C5-B13-M2-Q02', 'C5-B13-M2', 1, 'Đường tròn có bao nhiêu trục đối xứng?', 'A', 45, null, 'nhap', null, null, null),
  ('C5-B13-M2-Q03', 'C5-B13-M2', 2, 'Trục đối xứng của đường tròn là:', 'A', 60, null, 'nhap', null, null, null),
  ('C5-B13-M2-Q04', 'C5-B13-M2', 2, 'Cho $(O)$ và điểm $A$ thuộc $(O)$. Điểm đối xứng với $A$ qua $O$:', 'A', 60, null, 'nhap', null, null, null),
  ('C5-B13-M2-Q05', 'C5-B13-M2', 3, '$AB$ là một đường kính của $(O)$, điểm $M$ thuộc $(O)$. Điểm $M''$ đối xứng với $M$ qua đường thẳng $AB$:', 'A', 90, null, 'nhap', null, null, null),
  ('C5-B13-M2-Q06', 'C5-B13-M2', 3, 'Cho ($O; 5$ cm), điểm $A$ thuộc $(O)$, $A''$ đối xứng với $A$ qua $O$. Độ dài $AA''$ là:', 'A', 90, null, 'nhap', null, null, null),
  ('C5-B13-M2-Q07', 'C5-B13-M2', 2, 'Hình nào có tâm đối xứng và có vô số trục đối xứng?', 'A', 60, null, 'nhap', null, null, null),
  ('C5-B13-M2-Q08', 'C5-B13-M2', 4, 'Dây $AB$ của $(O)$ không đi qua tâm. Đường thẳng nào vừa là trục đối xứng của đường tròn vừa đi qua trung điểm của $AB$?', 'A', 120, null, 'nhap', null, null, null),
  ('C5-B13-M2-Q09', 'C5-B13-M2', 1, 'Đường thẳng chứa một đường kính của đường tròn là:', 'A', 45, null, 'nhap', null, null, null),
  ('C5-B13-M2-Q10', 'C5-B13-M2', 1, 'Cho điểm $A$ thuộc $(O)$. Điểm đối xứng với $A$ qua tâm $O$ là:', 'A', 45, null, 'nhap', null, null, null),
  ('C5-B13-M2-Q11', 'C5-B13-M2', 2, 'Hai điểm $A$, $B$ thuộc $(O)$ và đối xứng nhau qua $O$. Khi đó $AB$ là:', 'A', 60, null, 'nhap', null, null, null),
  ('C5-B13-M2-Q12', 'C5-B13-M2', 2, 'Cho điểm $M$ thuộc $(O)$. Lấy $M''$ đối xứng với $M$ qua một đường thẳng $d$ đi qua $O$. Khẳng định đúng là:', 'A', 60, null, 'nhap', null, null, null),
  ('C5-B13-M2-Q13', 'C5-B13-M2', 3, 'Trên ($O; 6$ cm) lấy điểm $A$. Gọi $B$ là điểm đối xứng với $A$ qua $O$, $C$ là điểm đối xứng với $A$ qua một đường thẳng $d$ đi qua $O$ ($C$ khác $A$). Khẳng định đúng là:', 'A', 90, null, 'nhap', null, null, null),
  ('C5-B13-M2-Q14', 'C5-B13-M2', 3, 'Cho dây $AB$ của $(O)$ không đi qua tâm, $H$ là trung điểm của $AB$. Đường thẳng $OH$:', 'A', 90, null, 'nhap', null, null, null),
  ('C5-B13-M2-Q15', 'C5-B13-M2', 4, 'Gấp đôi một tờ giấy hình tròn sao cho hai nửa trùng khít nhau. Nếp gấp luôn:', 'A', 120, null, 'nhap', null, null, null),
  ('C5-B13-M2-Q16', 'C5-B13-M2', 4, 'Để tìm tâm của một chiếc đĩa giấy tròn, bạn Nam gấp đĩa hai lần theo hai nếp gấp khác nhau, mỗi lần hai nửa trùng khít. Tâm của đĩa là:', 'A', 120, null, 'nhap', null, null, null),
  ('C5-B14-M1-Q01', 'C5-B14-M1', 1, 'Trong một đường tròn, dây lớn nhất là:', 'A', 45, null, 'nhap', null, null, null),
  ('C5-B14-M1-Q02', 'C5-B14-M1', 1, 'Đường tròn ($O; 6$ cm) có dây $AB$. Khẳng định đúng là:', 'A', 45, null, 'nhap', null, null, null),
  ('C5-B14-M1-Q03', 'C5-B14-M1', 2, 'Cho ($O; 5$ cm), dây $AB = 8$ cm. Khoảng cách từ $O$ đến dây $AB$ là:', 'A', 60, '{"loai":"duong-tron","mau":"day","nhan":{"R":"5 cm","day":"8 cm","d":"?"},"moTa":"Đường tròn tâm O, dây AB, OH vuông góc với AB tại H; bán kính 5 cm, dây 8 cm, khoảng cách cần tìm."}'::jsonb, 'nhap', null, null, null),
  ('C5-B14-M1-Q04', 'C5-B14-M1', 2, 'Đường kính vuông góc với một dây (không đi qua tâm) thì:', 'A', 60, null, 'nhap', null, null, null),
  ('C5-B14-M1-Q05', 'C5-B14-M1', 3, 'Cho ($O; 13$ cm), khoảng cách từ $O$ đến dây $AB$ là $5$ cm. Độ dài $AB$ là:', 'A', 90, '{"loai":"duong-tron","mau":"day","nhan":{"R":"13 cm","d":"5 cm","day":"?"},"moTa":"Đường tròn tâm O, dây AB, OH vuông góc với AB tại H; bán kính 13 cm, khoảng cách 5 cm, dây cần tìm."}'::jsonb, 'nhap', null, null, null),
  ('C5-B14-M1-Q06', 'C5-B14-M1', 3, 'Đường tròn có đường kính $10$ cm. Có dây nào dài $11$ cm không?', 'A', 90, null, 'nhap', null, null, null),
  ('C5-B14-M1-Q07', 'C5-B14-M1', 4, 'Cho $(O; R)$, hai dây $AB$ và $CD$ bằng nhau. Khẳng định đúng là:', 'A', 120, null, 'nhap', null, null, null),
  ('C5-B14-M1-Q08', 'C5-B14-M1', 4, 'Một miếng gỗ hình tròn bán kính $25$ cm bị cắt theo dây $AB$; khoảng cách từ tâm đến $AB$ là $7$ cm. Độ dài vết cắt $AB$ là:', 'A', 120, '{"loai":"duong-tron","mau":"day","nhan":{"R":"25 cm","d":"7 cm","day":"?"},"moTa":"Đường tròn tâm O, dây AB, OH vuông góc với AB tại H; bán kính 25 cm, khoảng cách 7 cm, dây cần tìm."}'::jsonb, 'nhap', null, null, null),
