  ('C5-B16-M3-Q12', 'C5-B16-M3', 2, '$MA$, $MB$ là hai tiếp tuyến của $(O)$ ($A$, $B$ là tiếp điểm), góc $AMB = 80^{\circ}$. Số đo góc $AOB$ là:', 'A', 60, '{"loai":"duong-tron","mau":"hai-tiep-tuyen","nhan":{"goc":"80°"},"moTa":"Đường tròn tâm O, hai tiếp tuyến MA, MB; góc 80°."}'::jsonb, 'nhap', null, null, null),
  ('C5-B16-M3-Q13', 'C5-B16-M3', 2, '$MA$, $MB$ là hai tiếp tuyến của $(O)$ ($A$, $B$ là tiếp điểm), góc $AMB = 50^{\circ}$. Số đo góc $AMO$ là:', 'A', 60, '{"loai":"duong-tron","mau":"hai-tiep-tuyen","nhan":{"goc":"50°"},"moTa":"Đường tròn tâm O, hai tiếp tuyến MA, MB; góc 50°."}'::jsonb, 'nhap', null, null, null),
  ('C5-B16-M3-Q14', 'C5-B16-M3', 3, '$MA$, $MB$ là hai tiếp tuyến của ($O; 3$ cm) ($A$, $B$ là tiếp điểm), $OM = 5$ cm. Độ dài dây $AB$ là:', 'A', 90, '{"loai":"duong-tron","mau":"hai-tiep-tuyen","nhan":{"R":"3 cm","OM":"5 cm","day":"AB = ?"},"moTa":"Đường tròn tâm O, hai tiếp tuyến MA, MB; bán kính 3 cm, OM 5 cm, dây AB cần tìm."}'::jsonb, 'nhap', null, null, null),
  ('C5-B16-M3-Q15', 'C5-B16-M3', 3, '$MA$, $MB$ là hai tiếp tuyến của ($O; 4$ cm) ($A$, $B$ là tiếp điểm), góc $AMB = 90^{\circ}$. Tứ giác $OAMB$ là:', 'A', 90, null, 'nhap', null, null, null),
  ('C5-B16-M3-Q16', 'C5-B16-M3', 4, 'Đường tròn $(I)$ tiếp xúc với ba cạnh của tam giác $ABC$ vuông tại $A$ có $AB = 6$, $AC = 8$; tiếp điểm trên $AB$ là $D$. Độ dài $AD$ là:', 'A', 120, null, 'nhap', null, null, null),
