  ('C5-B17-M1-Q07', 'C5-B17-M1', 2, 'Hai chiếc vòng tròn đặt chồng lên nhau một phần trên mặt bàn, mép hai vòng gặp nhau tại hai điểm. Hai đường tròn (mép vòng):', 'A', 60, null, 'nhap', null, null, null),
