  ('C5-B17-M1-Q13', 'C5-B17-M1', 3, '$(O)$ và $(O'')$ cắt nhau tại $A$ và $B$; $OO''$ cắt $AB$ tại $H$. Khẳng định đúng là:', 'A', 90, null, 'nhap', null, null, null),
  ('C5-B17-M1-Q14', 'C5-B17-M1', 3, 'Hai đường tròn ($O; 5$ cm) và ($O''; 5$ cm) cắt nhau tại $A$, $B$ với $OO'' = 8$ cm. Độ dài dây chung $AB$ là:', 'A', 90, '{"loai":"duong-tron","mau":"day-chung","nhan":{"R":"5 cm","d":"OO′ = 8 cm","day":"AB = ?"},"moTa":"Hai đường tròn (O) và (O′) cắt nhau tại A, B; OO′ cắt AB tại H; bán kính 5 cm, khoảng cách OO′ = 8 cm, dây AB cần tìm."}'::jsonb, 'nhap', null, null, null),
